(function () {
  'use strict';
  var FILES = [{"name":"demo/aflow.css","mime":"text/css","data":"/* =========================================================\n   AFlow · 算法解剖引擎样式\n   浅色主题，配色与主站令牌一致。三个案例包共用同一份。\n   ========================================================= */\n.af {\n  --af-ink: #242b2e; --af-ink2: #4d565b; --af-ink3: #79828a; --af-ink4: #9ba3a9;\n  --af-line: #e9e4d8; --af-line2: #f0ece1;\n  --af-jade: #2f7d6b; --af-jade-l: #e6f1ec; --af-jade-d: #22604f;\n  --af-clay: #b26a39; --af-red: #b05a51; --af-blue: #41699b;\n  border: 1px solid var(--af-line); border-radius: 12px; background: #fff;\n  padding: 14px 16px 12px; margin-top: 12px;\n}\n\n/* ---- 顶栏 ---- */\n.af-top { display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; }\n.af-head { min-width: 0; }\n.af-ttl {\n  display: inline-block; font-size: 10px; font-weight: 700; letter-spacing: .1em;\n  color: var(--af-jade); font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: var(--af-jade-l); border-radius: 4px; padding: 2px 8px; margin-right: 8px;\n}\n.af-sub { font-size: 12.5px; color: var(--af-ink2); }\n.af-ctrls { display: flex; align-items: center; gap: 4px; flex-shrink: 0; }\n.af-b {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  width: 28px; height: 26px; border-radius: 6px; cursor: pointer;\n  font-size: 12px; line-height: 1; font-family: inherit;\n  display: inline-flex; align-items: center; justify-content: center;\n  transition: all .14s;\n}\n.af-b:hover { border-color: var(--af-jade); color: var(--af-jade-d); background: var(--af-jade-l); }\n.af-play { width: 34px; font-size: 10px; }\n.af-sp {\n  border: 1px solid var(--af-line); background: #fff; color: var(--af-ink2);\n  border-radius: 6px; height: 26px; font-size: 11px; font-family: inherit; padding: 0 4px; cursor: pointer;\n}\n.af-sp:focus { outline: 2px solid var(--af-jade); outline-offset: 1px; }\n\n/* ---- 阶段轨道 ---- */\n.af-rail {\n  display: flex; gap: 4px; margin-top: 11px; overflow-x: auto; padding-bottom: 2px;\n  scrollbar-width: thin;\n}\n.af-node {\n  flex: 1 1 0; min-width: 96px; text-align: left; cursor: pointer; font-family: inherit;\n  border: 1px solid var(--af-line); background: #fff; border-radius: 7px;\n  padding: 5px 8px 6px; display: block; transition: all .16s; position: relative;\n}\n.af-node:hover { border-color: var(--af-jade); }\n.af-node .af-n {\n  display: inline-block; font-size: 9px; font-weight: 700; color: var(--af-ink4);\n  font-family: ui-monospace, monospace; margin-right: 5px;\n}\n.af-node .af-nm { font-size: 11.5px; color: var(--af-ink2); font-weight: 600; }\n.af-node .af-tg {\n  display: block; font-size: 9px; color: var(--af-ink4); margin-top: 1px;\n  font-family: ui-monospace, monospace; letter-spacing: .01em;\n}\n.af-node.done { border-color: #cfe3da; background: #f7fbf9; }\n.af-node.done .af-n { color: var(--af-jade); }\n.af-node.on { border-color: var(--af-jade); background: var(--af-jade-l); box-shadow: 0 0 0 2px rgba(47,125,107,.1); }\n.af-node.on .af-n { color: var(--af-jade-d); }\n.af-node.on .af-nm { color: var(--af-jade-d); }\n.af-node.on .af-tg { color: var(--af-jade); }\n\n/* ---- 进度条 ---- */\n.af-prog { height: 3px; background: var(--af-line2); border-radius: 2px; margin-top: 8px; overflow: hidden; }\n.af-prog i { display: block; height: 100%; background: var(--af-jade); border-radius: 2px; transition: width .06s linear; }\n\n/* ---- 舞台 ---- */\n.af-stage { margin-top: 10px; }\n.af-stage svg {\n  display: block; width: 100%; height: auto; max-height: 620px;\n  background: #fbfaf6; border: 1px solid var(--af-line); border-radius: 9px;\n}\n\n/* ---- 说明 + 读数 ---- */\n.af-meta { display: grid; grid-template-columns: 1fr 250px; gap: 12px; margin-top: 10px; align-items: start; }\n.af-note {\n  font-size: 12.5px; line-height: 1.72; color: var(--af-ink2);\n  background: #f4f3ef; border-left: 3px solid var(--af-jade); border-radius: 0 5px 5px 0;\n  padding: 8px 12px; min-height: 38px;\n}\n.af-note b { color: var(--af-ink); font-weight: 700; }\n.af-note code, .af-note .mono {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px;\n  background: #fff; border: 1px solid var(--af-line); border-radius: 3px; padding: 0 4px;\n}\n.af-stats { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }\n.af-stat {\n  background: #fff; border: 1px solid var(--af-line); border-radius: 6px;\n  padding: 4px 9px; min-width: 74px; flex: 1 1 auto;\n}\n.af-stat .k { display: block; font-size: 9.5px; color: var(--af-ink4); letter-spacing: .02em; }\n.af-stat .v {\n  display: block; font-family: ui-monospace, monospace; font-size: 13px;\n  font-weight: 600; color: var(--af-ink); margin-top: 1px;\n}\n.af-stat.t-ok .v { color: var(--af-jade-d); }\n.af-stat.t-warn .v { color: var(--af-clay); }\n.af-stat.t-bad .v { color: var(--af-red); }\n\n.af-count { margin-top: 7px; font-size: 10.5px; color: var(--af-ink4); font-family: ui-monospace, monospace; text-align: right; }\n\n@media (max-width: 860px) {\n  .af-meta { grid-template-columns: 1fr; }\n  .af-node { min-width: 84px; }\n  .af-node .af-nm { font-size: 11px; }\n}\n"},{"name":"demo/aflow.js","mime":"text/javascript","data":"/* =========================================================\n   AFlow · 算法解剖引擎（纯前端，零依赖）\n   ---------------------------------------------------------\n   用途：把「模型算法从输入走到输出」拆成若干可播放的阶段。\n   每个阶段跑的是真实的一段中间计算（不是抽象节点示意），\n   引擎负责：阶段轨道 / 播放控制 / 进度 / 实时读数 / 说明文字。\n\n   两种阶段写法\n   ------------\n   A) SVG 阶段 —— 适合示意图型中间量\n      { name, tag, dur,\n        draw: function (t, g, ctx) {\n          return { svg: '...', stats: [{k,v,tone}], note: '...' };\n        } }\n\n   B) DOM 阶段 —— 适合逐像素 / 逐节点的真实计算动画\n      { name, tag, dur,\n        init: function (host) {          // 只跑一次，构建 DOM\n          return {\n            update: function (t, ctx) {  // 每帧调用，负责重绘\n              return { stats: [...], note: '...' };\n            }\n          };\n        } }\n\n   用法：\n     AFlow.create({\n       mount: document.getElementById('flowMount'),\n       state: {},\n       stages: [ ... ]\n     });\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* ---------------- 配色（浅色主题，与主站令牌一致） ---------------- */\n  var C = {\n    ink: '#242b2e', ink2: '#4d565b', ink3: '#79828a', ink4: '#9ba3a9',\n    line: '#e9e4d8', line2: '#f0ece1', paper: '#fbfaf6', card: '#ffffff',\n    jade: '#2f7d6b', jadeL: '#e6f1ec', jadeD: '#22604f',\n    clay: '#b26a39', clayL: '#f8ecdf',\n    blue: '#41699b', blueL: '#e7eef9',\n    purple: '#7e5a8d', purpleL: '#efe9f4',\n    amber: '#c98a2b', amberL: '#faf3e2',\n    red: '#b05a51', redL: '#f9e9e5',\n    gray: '#79828a', grayL: '#f1f1ee'\n  };\n\n  /* 三栏坐标系：输入 → 算法内部 → 输出。画布 1000×520 */\n  var COLS = [\n    { x: 18, w: 272 },\n    { x: 312, w: 372 },\n    { x: 706, w: 276 }\n  ];\n  var TOP = 30, PANEL_H = 440, RAIL_Y = 484;\n\n  /* ---------------- 绘图 helper ---------------- */\n  var G = {\n    C: C, COLS: COLS, TOP: TOP, PANEL_H: PANEL_H,\n\n    esc: function (s) {\n      return String(s == null ? '' : s)\n        .replace(/&/g, '&amp;').replace(/<\/g, '&lt;').replace(/>/g, '&gt;');\n    },\n    f: function (v, n) {\n      n = (n === undefined) ? 2 : n;\n      if (v === null || v === undefined || !isFinite(v)) return '—';\n      return Number(v).toFixed(n);\n    },\n    rect: function (x, y, w, h, o) {\n      o = o || {};\n      return '<rect x=\"' + x + '\" y=\"' + y + '\" width=\"' + Math.max(0, w) + '\" height=\"' + Math.max(0, h) +\n        '\" rx=\"' + (o.r == null ? 4 : o.r) + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') + '/>';\n    },\n    line: function (x1, y1, x2, y2, o) {\n      o = o || {};\n      return '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" x2=\"' + x2 + '\" y2=\"' + y2 +\n        '\" stroke=\"' + (o.stroke || C.line) + '\" stroke-width=\"' + (o.sw == null ? 1 : o.sw) + '\"' +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') + '/>';\n    },\n    path: function (d, o) {\n      o = o || {};\n      return '<path d=\"' + d + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.5 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.dash ? ' stroke-dasharray=\"' + o.dash + '\"' : '') +\n        (o.cap ? ' stroke-linecap=\"' + o.cap + '\"' : '') +\n        (o.join ? ' stroke-linejoin=\"' + o.join + '\"' : '') + '/>';\n    },\n    txt: function (x, y, s, o) {\n      o = o || {};\n      var size = o.size == null ? 11 : o.size;\n      var fill = o.fill || C.ink2;\n      var anchor = o.anchor || 'start';\n      var weight = o.weight ? ' font-weight=\"' + o.weight + '\"' : '';\n      var fam = o.mono ? ' font-family=\"ui-monospace,SFMono-Regular,Menlo,Consolas,monospace\"' : '';\n      var extra = (o.op != null ? ' opacity=\"' + o.op + '\"' : '') +\n        (o.ls ? ' letter-spacing=\"' + o.ls + '\"' : '');\n      return '<text x=\"' + x + '\" y=\"' + y + '\" text-anchor=\"' + anchor + '\" font-size=\"' + size +\n        '\" fill=\"' + fill + '\"' + weight + fam + extra + '>' + G.esc(s) + '<\/text>';\n    },\n    circle: function (cx, cy, r, o) {\n      o = o || {};\n      return '<circle cx=\"' + cx + '\" cy=\"' + cy + '\" r=\"' + r + '\" fill=\"' + (o.fill || 'none') + '\"' +\n        (o.stroke ? ' stroke=\"' + o.stroke + '\" stroke-width=\"' + (o.sw == null ? 1.2 : o.sw) + '\"' : '') +\n        (o.op != null ? ' opacity=\"' + o.op + '\"' : '') + '/>';\n    },\n    poly: function (pts, o) {\n      o = o || {};\n      var d = '';\n      for (var i = 0; i < pts.length; i++) d += (i ? 'L' : 'M') + pts[i][0].toFixed(1) + ' ' + pts[i][1].toFixed(1) + ' ';\n      return G.path(d + (o.close ? 'Z' : ''), o);\n    },\n    /* 标准三栏面板：全站统一的「输入 / 算法内部 / 输出」视觉语法 */\n    panel: function (ci, title, sub, color, dim) {\n      var c = COLS[ci];\n      var o = G.rect(c.x, TOP, c.w, PANEL_H, {\n        r: 8, fill: '#ffffff', stroke: dim ? '#efece1' : C.line, sw: 1\n      });\n      o += G.rect(c.x, TOP, c.w, 3, { r: 1.5, fill: color || C.line, op: dim ? 0.32 : 1 });\n      o += G.txt(c.x + 13, TOP + 25, title, { size: 12.5, fill: dim ? C.ink3 : C.ink, weight: 700 });\n      if (sub) o += G.txt(c.x + 13, TOP + 41, sub, { size: 10, fill: C.ink4 });\n      o += G.line(c.x, TOP + 50, c.x + c.w, TOP + 50, { stroke: C.line2 });\n      return o;\n    },\n    /* 栏间箭头：标出「数据流向下一层」 */\n    arrow: function (x, y, color, label, sub) {\n      var o = G.path('M' + x + ' ' + (y - 5) + 'L' + (x + 11) + ' ' + y + 'L' + x + ' ' + (y + 5) +\n        'L' + (x + 3) + ' ' + y + 'Z', { fill: color || C.line });\n      if (label) o += G.txt(x - 2, y - 11, label, { size: 9.5, fill: color || C.ink3, anchor: 'middle', weight: 700 });\n      if (sub) o += G.txt(x - 2, y + 18, sub, { size: 8.5, fill: C.ink4, anchor: 'middle' });\n      return o;\n    },\n    /* 数据形态缎带：把「输入张量 → 中间张量 → 输出张量」的形状串成一条 */\n    shapes: function (list, active) {\n      if (!list || !list.length) return '';\n      var o = '', x = 18, w = 964;\n      var n = list.length, pad = 7;\n      var cw = (w - pad * (n - 1)) / n;\n      for (var i = 0; i < n; i++) {\n        var on = (i === active);\n        o += G.rect(x, RAIL_Y, cw, 24, {\n          r: 5, fill: on ? C.jadeL : '#ffffff', stroke: on ? C.jade : C.line, sw: on ? 1.3 : 1\n        });\n        o += G.txt(x + cw / 2, RAIL_Y + 16, list[i], {\n          size: 9.5, anchor: 'middle', mono: true,\n          fill: on ? C.jadeD : C.ink3, weight: on ? 700 : 400\n        });\n        if (i < n - 1) o += G.txt(x + cw + pad / 2, RAIL_Y + 16, '→', { size: 10, fill: C.ink4, anchor: 'middle' });\n        x += cw + pad;\n      }\n      return o;\n    },\n    axes: function (x, y, w, h, o) {\n      o = o || {};\n      var s = G.rect(x, y, w, h, { r: 4, fill: o.fill || '#fdfdfb', stroke: o.stroke || C.line2 });\n      if (o.nx) for (var i = 1; i < o.nx; i++) {\n        s += G.line(x + w * i / o.nx, y, x + w * i / o.nx, y + h, { stroke: C.line2, op: 0.7 });\n      }\n      if (o.ny) for (var j = 1; j < o.ny; j++) {\n        s += G.line(x, y + h * j / o.ny, x + w, y + h * j / o.ny, { stroke: C.line2, op: 0.7 });\n      }\n      return s;\n    }\n  };\n\n  /* ---------------- 引擎 ---------------- */\n  function create(opts) {\n    var mount = opts.mount;\n    if (!mount) return null;\n    var stages = (opts.stages || []).filter(function (s) { return s && (typeof s.draw === 'function' || typeof s.init === 'function'); });\n    if (!stages.length) return null;\n\n    var state = opts.state || {};\n    var idx = 0, t = 0, playing = opts.autoplay !== false, speed = 1;\n    var raf = null, lastTs = 0, dirty = true;\n    var domStage = null, domHandle = null;\n\n    mount.innerHTML =\n      '<div class=\"af\">' +\n      '  <div class=\"af-top\">' +\n      '    <div class=\"af-head\">' +\n      '      <span class=\"af-ttl\">' + G.esc(opts.title || '算法解剖') + '<\/span>' +\n      '      <span class=\"af-sub\">' + G.esc(opts.subtitle || '自动播放：输入怎么一步步变成输出') + '<\/span>' +\n      '    <\/div>' +\n      '    <div class=\"af-ctrls\">' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"prev\" title=\"上一步\">‹<\/button>' +\n      '      <button type=\"button\" class=\"af-b af-play\" data-a=\"play\" title=\"播放/暂停\">❚❚<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"next\" title=\"下一步\">›<\/button>' +\n      '      <button type=\"button\" class=\"af-b\" data-a=\"reset\" title=\"重播\">↺<\/button>' +\n      '      <select class=\"af-sp\" data-a=\"speed\" title=\"速度\">' +\n      '        <option value=\"0.5\">0.5×<\/option><option value=\"1\" selected>1×<\/option>' +\n      '        <option value=\"1.5\">1.5×<\/option><option value=\"2\">2×<\/option>' +\n      '      <\/select>' +\n      '    <\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-rail\"><\/div>' +\n      '  <div class=\"af-prog\"><i><\/i><\/div>' +\n      '  <div class=\"af-stage\"><\/div>' +\n      '  <div class=\"af-meta\">' +\n      '    <div class=\"af-note\"><\/div>' +\n      '    <div class=\"af-stats\"><\/div>' +\n      '  <\/div>' +\n      '  <div class=\"af-count\"><\/div>' +\n      '<\/div>';\n\n    var $ = function (sel) { return mount.querySelector(sel); };\n    var stageEl = $('.af-stage');\n    var railEl = $('.af-rail');\n    var progEl = $('.af-prog i');\n    var noteEl = $('.af-note');\n    var statsEl = $('.af-stats');\n    var countEl = $('.af-count');\n    var playBtn = $('[data-a=\"play\"]');\n\n    /* ---- 阶段轨道 ---- */\n    var nodeEls = stages.map(function (s, i) {\n      var b = document.createElement('button');\n      b.type = 'button';\n      b.className = 'af-node';\n      b.innerHTML = '<span class=\"af-n\">' + (i + 1) + '<\/span>' +\n        '<span class=\"af-nm\">' + G.esc(s.name) + '<\/span>' +\n        (s.tag ? '<span class=\"af-tg\">' + G.esc(s.tag) + '<\/span>' : '');\n      b.addEventListener('click', function () { goto(i); });\n      railEl.appendChild(b);\n      return b;\n    });\n\n    function goto(i) {\n      var ni = Math.max(0, Math.min(stages.length - 1, i));\n      if (ni !== idx) { disposeDom(); }\n      idx = ni; t = 0; dirty = true;\n      render(true);\n    }\n\n    /* 精确跳到某阶段的某个进度（0—1）。测试与「定位某一帧」用。 */\n    function seek(i, tt) {\n      goto(i);\n      t = Math.max(0, Math.min(1, tt == null ? 0 : tt));\n      dirty = true;\n      render(true);\n    }\n\n    function disposeDom() {\n      if (domHandle && typeof domHandle.destroy === 'function') {\n        try { domHandle.destroy(); } catch (e) { }\n      }\n      domHandle = null; domStage = null;\n    }\n\n    function totalDur() {\n      var s = 0;\n      for (var i = 0; i < stages.length; i++) s += (stages[i].dur || 2200);\n      return s;\n    }\n\n    function elapsed() {\n      var s = 0;\n      for (var i = 0; i < idx; i++) s += (stages[i].dur || 2200);\n      return s + t * (stages[idx].dur || 2200);\n    }\n\n    function render(force) {\n      if (!dirty && !force) return;\n      dirty = false;\n      var st = stages[idx];\n      var res = {};\n\n      try {\n        if (typeof st.init === 'function') {\n          /* DOM 阶段：init 只在进入该阶段时跑一次 */\n          if (domStage !== idx) {\n            disposeDom();\n            stageEl.innerHTML = '';\n            var host = document.createElement('div');\n            host.className = 'af-dom';\n            stageEl.appendChild(host);\n            domHandle = st.init(host) || {};\n            domStage = idx;\n          }\n          res = domHandle.update ? (domHandle.update(t, { index: idx, stage: st, state: state, api: api }) || {}) : {};\n        } else {\n          res = st.draw(t, G, { index: idx, stage: st, state: state, api: api }) || {};\n          stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\">' +\n            (res.svg || '') + '<\/svg>';\n        }\n      } catch (err) {\n        disposeDom();\n        stageEl.innerHTML = '<svg viewBox=\"0 0 1000 520\" preserveAspectRatio=\"xMidYMid meet\">' +\n          G.panel(1, '这一段出了点问题', String(err && err.message || err), C.red) +\n          G.txt(500, 260, '（算法计算中断，其余阶段不受影响）', { size: 11, fill: C.ink3, anchor: 'middle' }) +\n          '<\/svg>';\n        res = {\n          stats: [],\n          note: '<b style=\"color:' + C.red + '\">绘制失败：<\/b>' + G.esc(String(err && err.message || err))\n        };\n      }\n\n      /* 统计格 */\n      var stats = res.stats || [];\n      var h = '';\n      for (var i = 0; i < stats.length; i++) {\n        var s0 = stats[i];\n        h += '<div class=\"af-stat' + (s0.tone ? ' t-' + s0.tone : '') + '\">' +\n          '<span class=\"k\">' + G.esc(s0.k) + '<\/span><b class=\"v\">' + G.esc(s0.v) + '<\/b><\/div>';\n      }\n      statsEl.innerHTML = h;\n\n      noteEl.innerHTML = res.note || '';\n\n      for (var j = 0; j < nodeEls.length; j++) {\n        nodeEls[j].className = 'af-node' + (j === idx ? ' on' : (j < idx ? ' done' : ''));\n      }\n      countEl.textContent = '第 ' + (idx + 1) + ' / ' + stages.length + ' 步 · ' + (st.name || '');\n\n      progEl.style.width = (elapsed() / totalDur() * 100).toFixed(2) + '%';\n\n      playBtn.textContent = playing ? '❚❚' : '▶';\n      playBtn.title = playing ? '暂停' : '播放';\n    }\n\n    /* ---- 播放循环 ---- */\n    function tick(ts) {\n      raf = requestAnimationFrame(tick);\n      if (!lastTs) lastTs = ts;\n      var dt = Math.min(120, ts - lastTs);\n      lastTs = ts;\n      if (playing) {\n        var dur = stages[idx].dur || 2200;\n        t += (dt * speed) / dur;\n        if (t >= 1) {\n          if (idx < stages.length - 1) { disposeDom(); idx++; t = 0; }\n          else if (opts.loop !== false) { disposeDom(); idx = 0; t = 0; }\n          else { t = 1; playing = false; }\n        }\n        dirty = true;\n      }\n      if (dirty) render();\n    }\n\n    /* ---- 控制 ---- */\n    mount.querySelectorAll('.af-b, .af-sp').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var a = btn.getAttribute('data-a');\n        if (a === 'play') { playing = !playing; lastTs = 0; dirty = true; render(); }\n        else if (a === 'reset') { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); }\n        else if (a === 'prev') { if (t > 0.12) { t = 0; } else { goto(idx - 1); } dirty = true; render(); }\n        else if (a === 'next') { goto(idx + 1); }\n        else if (a === 'speed') { speed = parseFloat(btn.value) || 1; }\n      });\n    });\n    var sp = mount.querySelector('[data-a=\"speed\"]');\n    if (sp) sp.addEventListener('change', function () { speed = parseFloat(this.value) || 1; });\n\n    /* ---- 对外 API ---- */\n    var api = {\n      goto: goto,\n      seek: seek,\n      restart: function () { disposeDom(); idx = 0; t = 0; playing = true; lastTs = 0; dirty = true; render(); },\n      play: function () { playing = true; dirty = true; render(); },\n      pause: function () { playing = false; dirty = true; render(); },\n      refresh: function () { dirty = true; render(); },\n      get index() { return idx; },\n      setData: function (k, v) { state[k] = v; dirty = true; },\n      getData: function (k) { return state[k]; },\n      destroy: function () {\n        if (raf) cancelAnimationFrame(raf);\n        raf = null;\n        disposeDom();\n        mount.innerHTML = '';\n      }\n    };\n    if (opts.onReady) opts.onReady(api);\n\n    render(true);\n    raf = requestAnimationFrame(tick);\n    return api;\n  }\n\n  global.AFlow = { create: create, C: C, G: G, COLS: COLS };\n})(typeof window !== 'undefined' ? window : this);\n"},{"name":"demo/aiq.css","mime":"text/css","data":"/* =========================================================\n   AI 三问 · 可运行示范页通用区块\n   ---------------------------------------------------------\n   01 为什么（传统做法 vs AI 做法的同一段数据对照）\n   02 是什么（把业务对象翻译成算法可处理的形式）\n   03 怎样实现（五步工程路线，可跳到下方逐帧解剖）\n   依赖各包 demo.css 里的 --jade / --clay / --blue / --ink*\n   ========================================================= */\n\n.aiq {\n  margin: 0 0 18px; padding: 15px 18px 16px;\n  background: linear-gradient(180deg, #fbfaf6 0%, #ffffff 52%);\n  border: 1px solid var(--line, #e9e4d8); border-radius: 12px;\n}\n.aiq-top { display: flex; align-items: flex-start; gap: 10px; margin-bottom: 12px; }\n.aiq-chip {\n  flex: none; font-size: 10px; font-weight: 700; letter-spacing: .12em;\n  color: var(--jade, #2f7d6b); background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  border-radius: 999px; padding: 3px 9px; margin-top: 1px;\n}\n.aiq-lede { margin: 0; font-size: 13px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-lede b { color: var(--ink, #242b2e); }\n\n.aiq-grid { display: grid; grid-template-columns: 1.32fr 1fr 1fr; gap: 11px; }\n@media (max-width: 1040px) and (min-width: 760px) {\n  .aiq-grid { grid-template-columns: 1fr 1fr; grid-template-areas: \"a a\" \"b c\"; }\n  .aiq-card.q1 { grid-area: a; }\n  .aiq-card.q2 { grid-area: b; }\n  .aiq-card.q3 { grid-area: c; }\n}\n@media (max-width: 759px) { .aiq-grid { grid-template-columns: 1fr; } }\n.aiq-foot { margin: auto 0 0; padding-top: 2px; font-size: 10.5px; line-height: 1.5; color: var(--ink-4, #9ba3a9); }\n\n.aiq-card {\n  display: flex; flex-direction: column; gap: 9px;\n  border: 1px solid var(--line, #e9e4d8); border-radius: 10px;\n  background: #fff; padding: 11px 12px 11px;\n}\n.aiq-hd {\n  display: flex; align-items: center; gap: 7px;\n  padding-bottom: 8px; border-bottom: 1px dashed var(--line, #e9e4d8);\n}\n.aiq-hd .n {\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 10.5px; font-weight: 700; color: #fff;\n  border-radius: 5px; padding: 2px 6px; line-height: 1.5;\n}\n.aiq-hd > div { display: flex; align-items: baseline; gap: 4px; }\n.aiq-hd b { font-size: 14px; color: var(--ink, #242b2e); letter-spacing: .01em; }\n.aiq-hd em {\n  font-style: normal; font-size: 9px; letter-spacing: .16em; color: var(--ink-4, #9ba3a9);\n}\n.aiq-card.q1 .aiq-hd .n { background: var(--clay, #b26a39); }\n.aiq-card.q2 .aiq-hd .n { background: var(--blue, #41699b); }\n.aiq-card.q3 .aiq-hd .n { background: var(--jade, #2f7d6b); }\n\n/* ---------- 01 为什么：曲线对照 ---------- */\n.aiq-switch {\n  display: inline-flex; align-self: flex-start; gap: 2px; padding: 2px;\n  background: var(--card, #fbfaf6); border: 1px solid var(--line, #e9e4d8); border-radius: 999px;\n}\n.aiq-switch button {\n  font: inherit; font-size: 11.5px; line-height: 1.5; cursor: pointer;\n  border: 0; background: transparent; color: var(--ink-3, #79828a);\n  padding: 3px 11px; border-radius: 999px; transition: all .15s;\n}\n.aiq-switch button:hover { color: var(--ink, #242b2e); }\n.aiq-switch button.on {\n  background: #fff; color: var(--ink, #242b2e); font-weight: 600;\n  box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n}\n.aiq-fig { margin: 1px 0 0; }\n.aiq-fig svg { display: block; width: 100%; height: auto; }\n\n.aiq-nums {\n  display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;\n  margin: 0; padding: 0; list-style: none;\n}\n.aiq-nums li {\n  background: var(--card, #fbfaf6); border: 1px solid #efeadf; border-radius: 7px;\n  padding: 5px 6px 6px; text-align: center;\n}\n.aiq-nums b {\n  display: block; font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 14.5px; line-height: 1.25; color: var(--ink-2, #4d565b);\n  font-variant-numeric: tabular-nums; transition: color .2s;\n}\n.aiq-nums span { display: block; font-size: 10px; color: var(--ink-3, #79828a); line-height: 1.35; margin-top: 2px; }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"good\"] b { color: var(--jade, #2f7d6b); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"bad\"] b { color: var(--clay, #b26a39); }\n.aiq-card[data-mode=\"new\"] .aiq-nums li[data-tone=\"neut\"] b { color: var(--ink, #242b2e); }\n\n.aiq-note { margin: 0; font-size: 11.5px; line-height: 1.62; color: var(--ink-3, #79828a); }\n.aiq-note b { color: var(--ink-2, #4d565b); }\n.aiq-note .hl-bad { color: var(--clay, #b26a39); font-weight: 600; }\n.aiq-note .hl-good { color: var(--jade, #2f7d6b); font-weight: 600; }\n\n/* ---------- 02 是什么：翻译管线 + 式子 ---------- */\n.aiq-say { margin: 0; font-size: 12.5px; line-height: 1.7; color: var(--ink-2, #4d565b); }\n.aiq-say b { color: var(--ink, #242b2e); }\n.aiq-pipe { display: flex; flex-direction: column; }\n.aiq-pipe .p {\n  position: relative; padding: 5px 8px 5px 27px; border-radius: 6px;\n  background: var(--card, #fbfaf6); font-size: 11.5px; line-height: 1.5; color: var(--ink-3, #79828a);\n}\n.aiq-pipe .p i {\n  position: absolute; left: 8px; top: 6px; font-style: normal;\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px;\n  color: var(--blue, #41699b); font-weight: 700; letter-spacing: .02em;\n}\n.aiq-pipe .p b { color: var(--ink-2, #4d565b); font-weight: 600; }\n.aiq-pipe .ar { display: grid; place-items: center; height: 11px; }\n.aiq-pipe .ar::before {\n  content: \"\"; width: 1px; height: 7px; background: #ddd6c8;\n  box-shadow: 0 7px 0 -2px #ddd6c8;\n}\n.aiq-eq {\n  margin: 0; padding: 6px 9px; border-radius: 7px;\n  background: var(--jade-bg, #e6f1ec); border: 1px solid #cfe3d9;\n  font-family: ui-monospace, \"SF Mono\", Consolas, monospace;\n  font-size: 11px; line-height: 1.8; color: #1f5f4d;\n  overflow-x: auto; white-space: nowrap;\n}\n.aiq-eq em { font-style: normal; color: #5f8f80; font-size: 10px; }\n.aiq-fit { margin: 0; padding: 0; list-style: none; font-size: 11.5px; line-height: 1.56; color: var(--ink-2, #4d565b); }\n.aiq-fit li { position: relative; padding-left: 15px; }\n.aiq-fit li + li { margin-top: 2px; }\n.aiq-fit li i { position: absolute; left: 0; top: 0; font-style: normal; font-weight: 700; }\n.aiq-fit .y i { color: var(--jade, #2f7d6b); }\n.aiq-fit .n i { color: var(--clay, #b26a39); }\n\n/* ---------- 03 怎样实现：五步 + 跳转 ---------- */\n.aiq-steps { margin: 0; padding: 0; list-style: none; counter-reset: aiqs; }\n.aiq-steps li {\n  position: relative; padding-left: 20px;\n  font-size: 11.5px; line-height: 1.55; color: var(--ink-2, #4d565b);\n}\n.aiq-steps li + li { margin-top: 5px; }\n.aiq-steps li::before {\n  counter-increment: aiqs; content: counter(aiqs);\n  position: absolute; left: 0; top: 1px; width: 14px; height: 14px;\n  border-radius: 50%; background: var(--jade-bg, #e6f1ec); color: var(--jade, #2f7d6b);\n  font-family: ui-monospace, Consolas, monospace; font-size: 9px; font-weight: 700;\n  display: grid; place-items: center;\n}\n.aiq-steps li b { color: var(--ink, #242b2e); font-weight: 600; }\n.aiq-steps li code {\n  font-family: ui-monospace, Consolas, monospace; font-size: 10px;\n  background: #f3f0e8; border-radius: 3px; padding: 0 3px; color: #5c666b;\n}\n.aiq-jump {\n  margin-top: auto; padding-top: 8px; border-top: 1px dashed var(--line, #e9e4d8);\n  display: flex; align-items: center; justify-content: space-between; gap: 8px;\n}\n.aiq-jump span { font-size: 11px; color: var(--ink-4, #9ba3a9); }\n.aiq-jump a {\n  font-size: 11.5px; font-weight: 600; color: var(--jade, #2f7d6b);\n  text-decoration: none; white-space: nowrap;\n}\n.aiq-jump a:hover { color: #1f5f4d; text-decoration: underline; }\n\n/* 折叠态的三问（窄屏或用户收起时） */\n@media (max-width: 720px) {\n  .aiq { padding: 13px 12px 14px; }\n  .aiq-top { flex-direction: column; gap: 6px; }\n  .aiq-nums b { font-size: 13.5px; }\n}\n\n/* ---------- 03 卡内的踩坑提示 ---------- */\n.aiq-warn {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: var(--clay-bg, #f7ece2); border: 1px solid #eed9c6;\n  font-size: 11.5px; line-height: 1.6; color: #8a4f28;\n}\n.aiq-warn b { display: block; font-size: 10px; letter-spacing: .06em; color: var(--clay, #b26a39); margin-bottom: 2px; }\n\n/* ---------- 01 卡的对比表（没有可画的数字时用） ---------- */\n.aiq-tbl { width: 100%; border-collapse: collapse; font-size: 11.5px; }\n.aiq-tbl th {\n  font-size: 9.5px; font-weight: 600; color: var(--ink-4, #9ba3a9);\n  text-align: left; padding: 0 6px 5px; border-bottom: 1px solid var(--line, #e9e4d8);\n  letter-spacing: .02em;\n}\n.aiq-tbl th:first-child { padding-left: 0; }\n.aiq-tbl th:nth-child(2) { color: #8a9099; }\n.aiq-tbl th:nth-child(3) { color: var(--jade, #2f7d6b); }\n.aiq-tbl td {\n  padding: 5px 6px; border-bottom: 1px dashed #f2eee4;\n  color: var(--ink-2, #4d565b); line-height: 1.45; vertical-align: top;\n}\n.aiq-tbl td:first-child { padding-left: 0; color: var(--ink-3, #79828a); font-size: 11px; white-space: nowrap; }\n.aiq-tbl td:nth-child(2) { color: #7b838a; }\n.aiq-tbl td:nth-child(3) { color: #1f5f4d; font-weight: 500; }\n.aiq-tbl tr:last-child td { border-bottom: 0; }\n\n/* ---------- 01 卡的「代价」补充（填满短卡，也把边界说清） ---------- */\n.aiq-cost {\n  margin: 0; padding: 7px 9px; border-radius: 7px;\n  background: #f4f2ea; border: 1px solid #e8e3d5;\n  font-size: 11.5px; line-height: 1.6; color: #5f676c;\n}\n.aiq-cost b { display: block; font-size: 10px; letter-spacing: .06em; color: #8a9099; margin-bottom: 2px; }\n"},{"name":"demo/aiq.js","mime":"text/javascript","data":"/* =========================================================\n   AI 三问 · 交互（只服务 01「为什么」卡的曲线对照）\n   ---------------------------------------------------------\n   同一段数据、同一条劣化曲线，切换「传统做法 / AI 做法」：\n   传统只在越过阈值那一刻报警；AI 在曲线还落在正常区间时就\n   从「偏离自身基线」的趋势里看出苗头。图上同时给出两处标记、\n   提前量与三个指标数字。\n   无依赖，data-* 配置，多实例安全。\n   ========================================================= */\n(function () {\n  'use strict';\n  var NS = 'http://www.w3.org/2000/svg';\n\n  function mk(name, attrs) {\n    var e = document.createElementNS(NS, name);\n    for (var k in attrs) if (attrs.hasOwnProperty(k)) e.setAttribute(k, attrs[k]);\n    return e;\n  }\n  function txt(s, x, y, o) {\n    var t = mk('text', {\n      x: x, y: y,\n      'font-size': (o && o.size) || 9.5,\n      fill: (o && o.fill) || '#79828a',\n      'text-anchor': (o && o.anchor) || 'start',\n      'font-family': 'ui-monospace, \"SF Mono\", Consolas, monospace',\n      'font-weight': (o && o.weight) || 400\n    });\n    t.textContent = s;\n    return t;\n  }\n\n  /* 曲线：t∈[0,100] → 归一化高度 v∈[0,1]（1=顶部） */\n  function valAt(t, shape, onset) {\n    var a;\n    if (t <= onset) a = 0.295 + 0.095 * (t / Math.max(1, onset));\n    else a = 0.39 + 0.55 * Math.pow((t - onset) / (100 - onset), 1.55);\n    return shape === 'fall' ? 1 - a : a;\n  }\n\n  var W = 420, H = 150, L = 30, R = 10, T = 12, B = 32;\n  function xOf(t) { return L + t / 100 * (W - L - R); }\n  function yOf(v) { return (H - B) - v * ((H - B) - T); }\n\n  /* 条形对比：同一批井/同一批任务，旧做法与新做法的指标代差 */\n  function drawBar(box, mode, cfg) {\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var rows = cfg.rows;\n    var W2 = 372, H2 = 150, TOP = 14, RH = 40, LAB = 92, BARX = 92, BARW = 186;\n    var svg = mk('svg', { viewBox: '0 0 ' + W2 + ' ' + H2, role: 'img' });\n    svg.setAttribute('aria-label', '旧做法与新做法的指标对比');\n\n    var i, r, oldOn = mode === 'old';\n    for (i = 0; i < rows.length; i++) {\n      r = rows[i];\n      var y = TOP + i * RH;\n      svg.appendChild(txt(r[0], 2, y + 11, { size: 10, fill: '#4d565b' }));\n      if (r[4]) svg.appendChild(txt(r[4], 2, y + 24, { size: 8.5, fill: '#9ba3a9' }));\n\n      /* 行首两枚色条：旧 / 新 */\n      svg.appendChild(mk('rect', { x: 0, y: y + 5, width: 2, height: 9, fill: '#8a9099', opacity: oldOn ? 0.9 : 0.25 }));\n      svg.appendChild(mk('rect', { x: 0, y: y + 20, width: 2, height: 9, fill: '#2f7d6b', opacity: oldOn ? 0.25 : 0.9 }));\n\n      /* 纯文本行（无数字可画条） */\n      if (!r[5]) {\n        svg.appendChild(txt(r[1], BARX, y + 12, { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 600 : 400 }));\n        svg.appendChild(txt(r[2], BARX, y + 27, { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 600 }));\n        continue;\n      }\n\n      /* 每行按自身量级归一：不同指标量纲不同，跨行比较没有意义 */\n      var rmax = Math.max(r[1], r[2]) || 1;\n      var wOld = Math.max(2, r[1] / rmax * BARW), wNew = Math.max(2, r[2] / rmax * BARW);\n      var unit = r[3] === '%' ? '%' : (r[3] ? ' ' + r[3] : '');\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 4, width: wOld, height: 9, rx: 2, fill: '#8a9099', opacity: oldOn ? 0.85 : 0.22 }));\n      svg.appendChild(txt(fmt(r[1]) + unit, BARX + BARW + 8, y + 12,\n        { size: 10, fill: oldOn ? '#4d565b' : '#b3b8bd', weight: oldOn ? 700 : 400 }));\n\n      svg.appendChild(mk('rect', { x: BARX, y: y + 19, width: wNew, height: 9, rx: 2, fill: '#2f7d6b', opacity: oldOn ? 0.22 : 0.88 }));\n      svg.appendChild(txt(fmt(r[2]) + unit, BARX + BARW + 8, y + 27,\n        { size: 10, fill: oldOn ? '#b3b8bd' : '#2f7d6b', weight: oldOn ? 400 : 700 }));\n    }\n\n    /* 图例 */\n    svg.appendChild(mk('rect', { x: BARX, y: H2 - 9, width: 8, height: 3, fill: '#8a9099', opacity: 0.85 }));\n    svg.appendChild(txt('旧做法', BARX + 12, H2 - 4, { size: 8.5, fill: '#79828a' }));\n    svg.appendChild(mk('rect', { x: BARX + 52, y: H2 - 9, width: 8, height: 3, fill: '#2f7d6b', opacity: 0.88 }));\n    svg.appendChild(txt('新做法', BARX + 64, H2 - 4, { size: 8.5, fill: '#79828a' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n  function fmt(v) {\n    var n = Number(v);\n    if (!isFinite(n)) return String(v);\n    return Math.abs(n) >= 100 ? n.toFixed(0) : (Math.abs(n) >= 10 ? n.toFixed(n % 1 ? 1 : 0) : n.toFixed(n % 1 ? 1 : 0));\n  }\n\n  function draw(box, mode, cfg) {\n    if (cfg.kind === 'bar') { drawBar(box, mode, cfg); return; }\n    var wrap = box.querySelector('.aiq-fig');\n    if (!wrap) return;\n    var svg = mk('svg', { viewBox: '0 0 ' + W + ' ' + H, role: 'img' });\n    svg.setAttribute('aria-label', '传统做法与 AI 做法的检出时机对比');\n\n    /* 网格 */\n    for (var g = 1; g <= 3; g++) {\n      svg.appendChild(mk('line', {\n        x1: L, y1: yOf(0.24 * g), x2: W - R, y2: yOf(0.24 * g),\n        stroke: '#f1ede2', 'stroke-width': 1\n      }));\n    }\n\n    /* 正常区间带 */\n    var lo = cfg.bandLo, hi = cfg.bandHi;\n    svg.appendChild(mk('rect', {\n      x: L, y: yOf(hi), width: W - L - R, height: Math.max(2, yOf(lo) - yOf(hi)),\n      fill: '#2f7d6b', opacity: 0.07\n    }));\n    svg.appendChild(txt('正常区间', W - R - 3, yOf(hi) + 9, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    /* 报警阈值 */\n    svg.appendChild(mk('line', {\n      x1: L, y1: yOf(cfg.thr), x2: W - R, y2: yOf(cfg.thr),\n      stroke: '#b26a39', 'stroke-width': 1.1, 'stroke-dasharray': '4 3', opacity: 0.6\n    }));\n    svg.appendChild(txt('阈值 θ', W - R - 3, yOf(cfg.thr) - 4, { anchor: 'end', size: 8.5, fill: '#b26a39' }));\n\n    /* 曲线 */\n    var d = '', i, v;\n    for (i = 0; i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      d += (i ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: d, fill: 'none', stroke: '#4d565b', 'stroke-width': 1.7,\n      'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 劣化起点 */\n    svg.appendChild(mk('line', {\n      x1: xOf(cfg.onset), y1: yOf(cfg.thr) - 2, x2: xOf(cfg.onset), y2: yOf(0.06),\n      stroke: '#cfc9bb', 'stroke-width': 1, 'stroke-dasharray': '2 3'\n    }));\n\n    /* 从判定点起，曲线高亮 */\n    var from = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var dd = '';\n    for (i = Math.round(from); i <= 100; i++) {\n      v = valAt(i, cfg.shape, cfg.onset);\n      dd += (dd ? 'L' : 'M') + xOf(i).toFixed(1) + ' ' + yOf(v).toFixed(1);\n    }\n    svg.appendChild(mk('path', {\n      d: dd, fill: 'none',\n      stroke: mode === 'new' ? '#2f7d6b' : '#b26a39',\n      'stroke-width': 2.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round'\n    }));\n\n    /* 底部时间轴上的「提前量」量尺 */\n    var yB = H - 15;\n    if (mode === 'new' && cfg.newAt < cfg.oldAt) {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.newAt), y1: yB, x2: xOf(cfg.oldAt), y2: yB,\n        stroke: '#2f7d6b', 'stroke-width': 2.4, opacity: 0.3, 'stroke-linecap': 'round'\n      }));\n      [cfg.newAt, cfg.oldAt].forEach(function (t) {\n        svg.appendChild(mk('line', {\n          x1: xOf(t), y1: yB - 3.5, x2: xOf(t), y2: yB + 3.5,\n          stroke: '#2f7d6b', 'stroke-width': 1.2\n        }));\n      });\n      svg.appendChild(txt('提前 ' + cfg.days + ' 天', (xOf(cfg.newAt) + xOf(cfg.oldAt)) / 2, yB - 5,\n        { anchor: 'middle', size: 9, fill: '#2f7d6b', weight: 600 }));\n    } else {\n      svg.appendChild(mk('line', {\n        x1: xOf(cfg.oldAt), y1: yB, x2: W - R, y2: yB,\n        stroke: '#b26a39', 'stroke-width': 2.4, opacity: 0.28, 'stroke-linecap': 'round'\n      }));\n      svg.appendChild(txt('这段没有任何预警', W - R - 3, yB - 5,\n        { anchor: 'end', size: 9, fill: '#b26a39', weight: 600 }));\n    }\n\n    /* 判定点 */\n    var tx = mode === 'new' ? cfg.newAt : cfg.oldAt;\n    var px = xOf(tx), py = yOf(valAt(tx, cfg.shape, cfg.onset));\n    var col = mode === 'new' ? '#2f7d6b' : '#b26a39';\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 6.5, fill: col, opacity: 0.15 }));\n    svg.appendChild(mk('circle', { cx: px, cy: py, r: 3.2, fill: col, stroke: '#fff', 'stroke-width': 1.3 }));\n\n    /* 标签固定在左上角，用细引线指到判定点：两种模式切换时位置不跳，便于对比 */\n    var label = mode === 'new' ? '这里就预警' : '越限才发现';\n    var tw = label.length * 9 + 11, th = 15;\n    var tX = L + 3, tY = T + 1;\n    svg.appendChild(mk('line', {\n      x1: tX + tw / 2, y1: tY + th, x2: px, y2: py - 5,\n      stroke: col, 'stroke-width': 0.8, 'stroke-dasharray': '2 3', opacity: 0.45\n    }));\n    svg.appendChild(mk('rect', {\n      x: tX, y: tY, width: tw, height: th, rx: 3.5,\n      fill: '#fffdf7', stroke: col, 'stroke-width': 0.8, 'stroke-opacity': 0.4\n    }));\n    svg.appendChild(txt(label, tX + 6, tY + 11, { size: 9, fill: col, weight: 600 }));\n\n    /* 轴与单位 */\n    svg.appendChild(txt('时间 →', L, H - 3, { size: 8.5, fill: '#9ba3a9' }));\n    svg.appendChild(txt(cfg.unit, W - R, T + 2, { anchor: 'end', size: 8.5, fill: '#9ba3a9' }));\n\n    wrap.innerHTML = '';\n    wrap.appendChild(svg);\n  }\n\n  function init(box) {\n    var cfg = {\n      shape: box.getAttribute('data-shape') || 'rise',\n      unit: box.getAttribute('data-unit') || '',\n      onset: parseFloat(box.getAttribute('data-onset')) || 55,\n      thr: parseFloat(box.getAttribute('data-thr')) || 0.72,\n      oldAt: parseFloat(box.getAttribute('data-old-at')) || 88,\n      newAt: parseFloat(box.getAttribute('data-new-at')) || 60,\n      days: box.getAttribute('data-days') || '',\n      kind: box.getAttribute('data-kind') || 'trend',\n      rows: (box.getAttribute('data-rows') || '').split(';').filter(function (x) { return x.trim(); }).map(function (x) {\n        var p = x.split('|');\n        var num = isFinite(parseFloat(p[1])) && isFinite(parseFloat(p[2]));\n        return [p[0] || '', num ? parseFloat(p[1]) : (p[1] || ''), num ? parseFloat(p[2]) : (p[2] || ''), p[3] || '', p[4] || '', num];\n      }),\n      bandLo: parseFloat(box.getAttribute('data-band-lo')) || 0.26,\n      bandHi: parseFloat(box.getAttribute('data-band-hi')) || 0.46\n    };\n    var btns = box.querySelectorAll('.aiq-switch button');\n    var nums = box.querySelectorAll('.aiq-nums b[data-old]');\n    var notes = box.querySelectorAll('.aiq-note [data-v]');\n\n    function set(mode) {\n      box.setAttribute('data-mode', mode);\n      [].forEach.call(btns, function (b) { b.classList.toggle('on', b.getAttribute('data-v') === mode); });\n      [].forEach.call(nums, function (n) {\n        var v = n.getAttribute('data-' + (mode === 'old' ? 'old' : 'new'));\n        if (v != null && v !== '') n.textContent = v;\n      });\n      [].forEach.call(notes, function (n) { n.hidden = n.getAttribute('data-v') !== mode; });\n      draw(box, mode, cfg);\n    }\n\n    if (!btns.length) { set('new'); return; }\n    [].forEach.call(btns, function (b) {\n      b.addEventListener('click', function () { set(b.getAttribute('data-v')); });\n    });\n    set('old');\n  }\n\n  function boot() {\n    [].forEach.call(document.querySelectorAll('[data-aiq]'), init);\n  }\n  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);\n  else boot();\n})();\n"},{"name":"demo/demo.css","mime":"text/css","data":"/* =========================================================\n   地质剖面遥感解译 · 示范页样式（整页模式，沙箱 iframe）\n   浅色主题：全部使用设计令牌 / 低饱和浅色 hex\n   ========================================================= */\n:root {\n  --jade: #2f7d6b;\n  --jade-bg: #e6f1ec;\n  --clay: #b26a39;\n  --clay-bg: #f7ece2;\n  --blue: #41699b;\n  --blue-bg: #e7eef9;\n  --ink: #242b2e;\n  --ink-2: #4d565b;\n  --ink-3: #79828a;\n  --ink-4: #9ba3a9;\n  --line: #e9e4d8;\n  --card: #fbfaf6;\n  --bg: #faf9f4;\n}\n\n* { box-sizing: border-box; }\n\nbody {\n  margin: 0;\n  padding: 20px 22px 26px;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14.5px/1.7 -apple-system, \"Segoe UI\", \"Microsoft YaHei\", system-ui, sans-serif;\n}\n\n/* ---------- 头部 ---------- */\n.hd { margin-bottom: 18px; }\n.kicker { font-size: 10.5px; letter-spacing: .14em; color: var(--jade); font-weight: 700; }\n.hd h1 { margin: 4px 0 6px; font-size: 21px; color: var(--ink); }\n.hd .sub { margin: 0; color: var(--ink-3); font-size: 13.5px; }\n\n/* ---------- 区块 ---------- */\n.sec {\n  margin-bottom: 26px; padding: 18px 20px;\n  background: var(--card); border: 1px solid var(--line); border-radius: 12px;\n}\n.sec-hd { margin-bottom: 12px; }\n.sec-no { font-size: 10.5px; letter-spacing: .12em; color: var(--ink-4); font-weight: 700; text-transform: uppercase; }\n.sec-hd h2 { margin: 3px 0 6px; font-size: 17px; color: var(--ink); }\n.sec-hd .leadline { margin: 0; color: var(--ink-3); font-size: 13px; }\n.sec-hd .leadline b { color: var(--ink); }\n\n/* ---------- 图例 ---------- */\n.legend { display: flex; flex-wrap: wrap; gap: 8px 14px; margin: 8px 0 4px; }\n.legend .lg { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; color: var(--ink-2); }\n.legend .lg i { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }\n\n/* ---------- 控件 ---------- */\n.ctl { display: flex; flex-wrap: wrap; gap: 14px 24px; align-items: center; margin-bottom: 12px; padding: 10px 12px; background: var(--bg); border: 1px solid var(--line); border-radius: 10px; }\n.ctl .btns { display: flex; flex-wrap: wrap; gap: 6px; }\n.ctl .btns button { font: inherit; font-size: 12.5px; padding: 5px 12px; border-radius: 8px; border: 1px solid var(--line); background: #fff; color: var(--ink-2); cursor: pointer; }\n.ctl .btns button.on, .ctl .btns button:hover { background: var(--jade); color: #fff; border-color: var(--jade); }\n.ctl .sl { display: flex; flex-direction: column; gap: 3px; min-width: 180px; }\n.ctl .sl label { font-size: 12.5px; color: var(--ink-2); display: flex; justify-content: space-between; align-items: center; }\n.ctl .sl output { font-family: ui-monospace, monospace; font-size: 13px; color: var(--jade); font-weight: 600; }\n.ctl input[type=range] { width: 100%; accent-color: var(--jade); }\n\n/* ---------- SVG 图 ---------- */\n.chart-wrap { width: 100%; }\n.chart-wrap svg { width: 100%; height: auto; display: block; border: 1px solid var(--line); border-radius: 8px; background: #fff; }\n.fg { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }\n.fg .cap { font-size: 12px; color: var(--ink-3); text-align: center; margin-top: 6px; }\n@media (max-width:720px){ .fg { grid-template-columns: 1fr; } }\n\n/* ---------- 结果读数行 ---------- */\n.rrow { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 12px; }\n.ro { flex: 1; min-width: 130px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 8px 12px; }\n.ro .k { display: block; font-size: 11px; color: var(--ink-4); margin-bottom: 2px; }\n.ro b { font-size: 15px; color: var(--ink); }\n.ro b.good { color: var(--jade); }\n.ro b.warn { color: var(--clay); }\n\n/* ---------- 提示 / 折叠 ---------- */\n.tip { margin: 10px 0 0; font-size: 12.5px; color: var(--ink-3); background: var(--jade-bg); border-radius: 8px; padding: 8px 12px; }\n.details { margin-top: 12px; }\n.details summary { cursor: pointer; font-size: 13px; color: var(--jade); font-weight: 600; }\n\n/* 算法解剖引擎在 aflow.css 里；AI 三问在 aiq.css 里 */\n"},{"name":"demo/demo.js","mime":"text/javascript","data":"/* =========================================================\n   钻井液性能智能调控 · 示范脚本（整页模式，运行在沙箱 iframe 里）\n   ---------------------------------------------------------\n   三屏：\n   屏 1  多源融合软测量：高频循环参数 → 连续性能趋势\n   屏 2  加量推荐：偏差 → 该加多少\n   屏 3  过调抑制：经验 vs 推荐加量 + 性能验收\n   所有计算都在浏览器里完成，纯前端。\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  /* =====================================================\n     纯模型层（Node 可 require 做单测；浏览器里继续往下走）\n     ===================================================== */\n  var Model = (function () {\n\n    function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n    function mulberry32(a) {\n      return function () {\n        a |= 0; a = a + 0x6D2B79F5 | 0;\n        var t = Math.imul(a ^ a >>> 15, 1 | a);\n        t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;\n        return ((t ^ t >>> 14) >>> 0) / 4294967296;\n      };\n    }\n\n    /* -----------------------------------------------------\n       合成高频循环参数（流量/温度/压力）\n       返回 { n, flow:[], temp:[], pres:[] }\n       ----------------------------------------------------- */\n    function genCirc(n, seed) {\n      var rnd = mulberry32(seed || 20261151);\n      var flow = new Float64Array(n), temp = new Float64Array(n), pres = new Float64Array(n);\n      for (var i = 0; i < n; i++) {\n        flow[i] = clamp(28 + Math.sin(i * 0.05) * 3 + (rnd() - 0.5) * 2, 20, 36);\n        temp[i] = clamp(46 + i * 0.04 + Math.sin(i * 0.08) * 2 + (rnd() - 0.5) * 1.5, 42, 70);\n        pres[i] = clamp(12 + Math.sin(i * 0.07) * 1.2 + (rnd() - 0.5) * 1, 9, 16);\n      }\n      return { n: n, flow: flow, temp: temp, pres: pres };\n    }\n\n    /* -----------------------------------------------------\n       多源融合软测量\n       高频循环参数 + 稀疏性能测量（每 10 点一个）→ 连续性能趋势。\n       mode 0 纯性能测量(稀疏) 1 多源融合。\n       返回 { sense: Float64Array, meas:[{i,v}], err }\n       ----------------------------------------------------- */\n    function softSense(circ, mode, n, seed) {\n      var rnd = mulberry32(seed || 20261152);\n      var sense = new Float64Array(n);\n      var meas = [];\n      /* 稀疏实测（真实性能） */\n      var trueV = [];\n      for (var i = 0; i < n; i++) {\n        /* 真实性能与温度/压力相关，缓慢变化 */\n        trueV.push(clamp(1.2 + circ.temp[i] * 0.01 + Math.sin(i * 0.06) * 0.05 + (rnd() - 0.5) * 0.02, 1.0, 2.2));\n      }\n      for (i = 0; i < n; i++) {\n        if (mode === 0) {\n          /* 纯稀疏：只在测量点有值，其余保持上次 */\n          if (i % 10 === 0) sense[i] = trueV[i];\n          else sense[i] = i > 0 ? sense[i - 1] : trueV[i];\n        } else {\n          /* 多源融合：用高频参数连续估算，测量点校正 */\n          var est = 1.2 + circ.temp[i] * 0.01 + Math.sin(i * 0.06) * 0.05;\n          if (i % 10 === 0) { sense[i] = trueV[i]; meas.push({ i: i, v: trueV[i] }); }\n          else sense[i] = est + (rnd() - 0.5) * 0.01;\n        }\n      }\n      /* 误差（相对真实） */\n      var err = 0;\n      for (i = 0; i < n; i++) err += Math.abs(sense[i] - trueV[i]) / n;\n      return { sense: sense, meas: meas, err: err, trueV: trueV };\n    }\n\n    /* -----------------------------------------------------\n       加量推荐\n       性能偏差 dev → 该加多少处理剂。\n       mode 0 经验(过调) 1 推荐(按偏差校准)。\n       返回 { dose: Float64Array }\n       ----------------------------------------------------- */\n    function doseRecommend(devs, mode, n) {\n      var dose = new Float64Array(n);\n      for (var i = 0; i < n; i++) {\n        var dev = devs[i];\n        if (mode === 0) {\n          /* 经验：猛加，容易过调 */\n          dose[i] = Math.abs(dev) * 3.2;\n        } else {\n          /* 推荐：按偏差幅度校准，小偏差少加 */\n          dose[i] = Math.abs(dev) * 1.6 + (dev > 0 ? 0.1 : 0.05);\n        }\n      }\n      return dose;\n    }\n\n    /* -----------------------------------------------------\n       过调抑制\n       对比经验 vs 推荐加量下的性能波动。\n       返回 { expDose, recDose, expWave, recWave, expOk, recOk }\n       ----------------------------------------------------- */\n    function oscillationCtrl(devs, mode, n) {\n      var expDose = doseRecommend(devs, 0, n);\n      var recDose = doseRecommend(devs, 1, n);\n      /* 加量后的性能偏差：\n         经验 = 猛加 → 抑制不足 + 累积振荡（偏离 0，来回摆）\n         推荐 = 按偏差校准 → 抑制到位（更接近 0） */\n      var expPerf = new Float64Array(n), recPerf = new Float64Array(n);\n      var expWave = 0, recWave = 0, expOk = 0, recOk = 0;\n      for (var i = 0; i < n; i++) {\n        expPerf[i] = clamp(devs[i] * 0.9 - (i > 0 ? expPerf[i - 1] : 0) * 0.15, -0.8, 0.8);\n        recPerf[i] = clamp(devs[i] * 0.3 - (i > 0 ? recPerf[i - 1] : 0) * 0.03, -0.5, 0.5);\n        expWave += Math.abs(expPerf[i]) / n;\n        recWave += Math.abs(recPerf[i]) / n;\n        if (Math.abs(expPerf[i]) < 0.25) expOk++;\n        if (Math.abs(recPerf[i]) < 0.25) recOk++;\n      }\n      return {\n        expDose: expDose, recDose: recDose, expPerf: expPerf, recPerf: recPerf,\n        expWave: expWave, recWave: recWave, expOk: expOk / n, recOk: recOk / n\n      };\n    }\n\n    return {\n      clamp: clamp, mulberry32: mulberry32,\n      genCirc: genCirc, softSense: softSense,\n      doseRecommend: doseRecommend, oscillationCtrl: oscillationCtrl\n    };\n  })();\n\n  /* Node 单测入口 */\n  if (typeof module !== 'undefined' && module.exports) {\n    module.exports = Model;\n    return;\n  }\n\n  /* =====================================================\n     浏览器接线（沙箱 iframe 内执行）\n     ===================================================== */\n  var doc = document;\n  var $ = function (id) { return doc.getElementById(id); };\n  var M = Model;\n\n  var state = {\n    nData: 100, senseMode: 1 /* 0 稀疏 1 融合 */, recMode: 1 /* 0 经验 1 推荐 */\n  };\n\n  var N = 100;\n  var circ = M.genCirc(N, 20261151);\n  var soft = M.softSense(circ, state.senseMode, N, 20261152);\n  /* 偏差 = 目标 - 软测 */\n  var devs = new Float64Array(N);\n  for (var i = 0; i < N; i++) devs[i] = 1.55 - soft.sense[i];\n  var ctrl = M.oscillationCtrl(devs, state.recMode, N);\n\n  global.RemoteBridge = {\n    M: M,\n    genCirc: M.genCirc, softSense: M.softSense,\n    doseRecommend: M.doseRecommend, oscillationCtrl: M.oscillationCtrl,\n    live: function () {\n      return { nData: state.nData, senseMode: state.senseMode, recMode: state.recMode };\n    }\n  };\n\n  function num(v, d) { return v.toFixed(d == null ? 1 : d); }\n  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }\n\n  function linePath(arr, x0, y0, xS, yS, color, dash) {\n    var s = '<path d=\"M';\n    for (var i = 0; i < arr.length; i++) {\n      s += (x0 + i * xS).toFixed(1) + ' ' + (y0 - arr[i] * yS).toFixed(1);\n      if (i < arr.length - 1) s += ' L';\n    }\n    s += '\" fill=\"none\" stroke=\"' + color + '\" stroke-width=\"' + (dash ? 1.8 : 2) + '\"' + (dash ? ' stroke-dasharray=\"5 3\"' : '') + '/>';\n    return s;\n  }\n\n  /* ---------- 屏 1 渲染：多源融合软测量 ---------- */\n  function renderSense() {\n    circ = M.genCirc(N, 20261151);\n    soft = M.softSense(circ, state.senseMode, N, 20261152);\n    var s = '';\n    var x0 = 40, y0 = 40, w = 300, h = 90;\n    s += '<text x=\"40\" y=\"24\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">性能软测量：' + (state.senseMode === 0 ? '纯稀疏测量' : '多源融合（高频参数）') + '<\/text>';\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y0 + h) + '\" x2=\"' + (x0 + w) + '\" y2=\"' + (y0 + h) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    /* 真实性能（绿虚） */\n    var trueArr = [];\n    for (var i = 0; i < N; i++) trueArr.push((soft.trueV[i] - 1.0) / 1.2);\n    s += linePath(trueArr, x0, y0 + h, w / N, h, '#2f7d6b', true);\n    /* 软测（蓝） */\n    var senseArr = [];\n    for (i = 0; i < N; i++) senseArr.push((soft.sense[i] - 1.0) / 1.2);\n    s += linePath(senseArr, x0, y0 + h, w / N, h, '#41699b', false);\n    /* 稀疏测量点 */\n    soft.meas.forEach(function (m) {\n      var px = x0 + m.i * w / N;\n      var py = y0 + h - (m.v - 1.0) / 1.2 * h;\n      s += '<circle cx=\"' + px + '\" cy=\"' + py + '\" r=\"3\" fill=\"#b26a39\"/>';\n    });\n    s += '<text x=\"' + (x0 + 6) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#2f7d6b\">真实<\/text>';\n    s += '<text x=\"' + (x0 + 46) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#41699b\">软测<\/text>';\n    s += '<text x=\"' + (x0 + 90) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#b26a39\">实测点<\/text>';\n    $('senseChart').innerHTML = s;\n    $('roErr').textContent = Math.round(soft.err * 100) + '%';\n    $('roSrc').textContent = state.senseMode === 0 ? '仅每班测量' : '高频参数融合';\n  }\n\n  /* ---------- 屏 2 渲染：加量推荐 ---------- */\n  function renderDose() {\n    circ = M.genCirc(N, 20261151);\n    soft = M.softSense(circ, state.senseMode, N, 20261152);\n    for (var i = 0; i < N; i++) devs[i] = 1.55 - soft.sense[i];\n    var dose = M.doseRecommend(devs, state.recMode, N);\n    var s = '';\n    var x0 = 40, y0 = 40, w = 300, h = 90;\n    s += '<text x=\"40\" y=\"24\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">处理剂加量推荐（' + (state.recMode === 0 ? '经验·易过调' : '按偏差校准') + '）<\/text>';\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y0 + h) + '\" x2=\"' + (x0 + w) + '\" y2=\"' + (y0 + h) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    var doseMax = Math.max.apply(null, Array.from(dose)) || 1;\n    var doseArr = [];\n    for (i = 0; i < N; i++) doseArr.push(dose[i] / (doseMax * 1.1));\n    s += linePath(doseArr, x0, y0 + h, w / N, h, '#b26a39', false);\n    /* 偏差底 */\n    var devArr = [];\n    var devMax = Math.max.apply(null, Array.from(devs).map(function (v) { return Math.abs(v); })) || 1;\n    for (i = 0; i < N; i++) devArr.push(devs[i] / (devMax * 1.2));\n    s += linePath(devArr, x0, y0 + h, w / N, h, '#7a8a9a', true);\n    s += '<text x=\"' + (x0 + 6) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#b26a39\">加量<\/text>';\n    s += '<text x=\"' + (x0 + 46) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#7a8a9a\">偏差<\/text>';\n    $('doseChart').innerHTML = s;\n    $('roDose').textContent = num(dose[N - 1], 2) + ' kg/m³';\n    $('roDev').textContent = num(devs[N - 1], 2);\n  }\n\n  /* ---------- 屏 3 渲染：过调抑制 ---------- */\n  function renderOsc() {\n    circ = M.genCirc(N, 20261151);\n    soft = M.softSense(circ, state.senseMode, N, 20261152);\n    for (var i = 0; i < N; i++) devs[i] = 1.55 - soft.sense[i];\n    var cExp = M.oscillationCtrl(devs, 0, N);\n    var cRec = M.oscillationCtrl(devs, 1, N);\n    var s = '';\n    var x0 = 40, y0 = 40, w = 300, h = 90;\n    s += '<text x=\"40\" y=\"24\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">加量后性能偏差：经验 vs 推荐（过调抑制）<\/text>';\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y0 + h) + '\" x2=\"' + (x0 + w) + '\" y2=\"' + (y0 + h) + '\" stroke=\"#9ba3a9\" stroke-width=\"1\"/>';\n    s += '<line x1=\"' + x0 + '\" y1=\"' + (y0 + h / 2) + '\" x2=\"' + (x0 + w) + '\" y2=\"' + (y0 + h / 2) + '\" stroke=\"#9ba3a9\" stroke-width=\"0.8\" stroke-dasharray=\"4 3\"/>';\n    var expArr = [], recArr = [];\n    for (var i = 0; i < N; i++) { expArr.push(cExp.expPerf[i] / 0.8); recArr.push(cRec.recPerf[i] / 0.8); }\n    s += linePath(expArr, x0, y0 + h / 2, w / N, h / 2, '#b26a39', false);\n    s += linePath(recArr, x0, y0 + h / 2, w / N, h / 2, '#2f7d6b', false);\n    s += '<text x=\"' + (x0 + 6) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#b26a39\">经验<\/text>';\n    s += '<text x=\"' + (x0 + 46) + '\" y=\"' + (y0 - 2) + '\" font-size=\"7.5\" fill=\"#2f7d6b\">推荐<\/text>';\n    /* 达标率双柱 */\n    var y2 = 160;\n    s += '<text x=\"40\" y=\"' + (y2 - 8) + '\" font-size=\"9\" fill=\"#4d565b\" font-weight=\"700\">性能达标率<\/text>';\n    s += '<rect x=\"40\" y=\"' + y2 + '\" width=\"110\" height=\"44\" fill=\"#d9b78e\"/>';\n    s += '<text x=\"95\" y=\"' + (y2 + 27) + '\" text-anchor=\"middle\" font-size=\"10\" fill=\"#4d565b\" font-weight=\"700\">' + Math.round(cExp.expOk * 100) + '%<\/text>';\n    s += '<text x=\"95\" y=\"' + (y2 + 40) + '\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#8a6b52\">经验加量<\/text>';\n    s += '<rect x=\"200\" y=\"' + y2 + '\" width=\"110\" height=\"44\" fill=\"#2f7d6b\"/>';\n    s += '<text x=\"255\" y=\"' + (y2 + 27) + '\" text-anchor=\"middle\" font-size=\"10\" fill=\"#fff\" font-weight=\"700\">' + Math.round(cRec.recOk * 100) + '%<\/text>';\n    s += '<text x=\"255\" y=\"' + (y2 + 40) + '\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"#b9d8cb\">推荐+抑过调<\/text>';\n    $('oscChart').innerHTML = s;\n    $('roWave').textContent = '波动 ' + num(cRec.recWave, 2) + '（经验 ' + num(cExp.expWave, 2) + '）';\n    $('roOk').textContent = Math.round(cRec.recOk * 100) + '%';\n    /* 回流清单 */\n    var rows = [\n      ['加量回流', state.recMode === 0 ? '经验·可能过调' : '推荐·按偏差校准', 'ok'],\n      ['性能反馈', '已录入', 'ok'],\n      ['波动改善', num(cExp.expWave - cRec.recWave, 2), 'ok']\n    ];\n    var rs = '';\n    for (var r = 0; r < rows.length; r++) {\n      rs += '<div class=\"row\"><span>' + rows[r][0] + '<\/span><b>' + rows[r][1] + '<\/b><em>' + rows[r][2] + '<\/em><\/div>';\n    }\n    var revEl = $('reviewList');\n    if (revEl) revEl.innerHTML = rs;\n  }\n\n  /* ---------- 事件绑定 ---------- */\n  function bind() {\n    var inSense = $('inSense');\n    if (inSense) inSense.addEventListener('input', function () {\n      state.senseMode = parseInt(inSense.value, 10);\n      $('outSense').textContent = state.senseMode === 0 ? '纯稀疏测量' : '多源融合';\n      renderSense(); renderDose(); renderOsc();\n    });\n    var inRec = $('inRec');\n    if (inRec) inRec.addEventListener('input', function () {\n      state.recMode = parseInt(inRec.value, 10);\n      $('outRec').textContent = state.recMode === 0 ? '经验加量' : '推荐+抑过调';\n      renderDose(); renderOsc();\n    });\n  }\n\n  /* 抽屉上报 */\n  function setupDrawer() {\n    if (window.parent === window) return;\n    var secs = [];\n    [['sec1', '多源融合软测量', 'senseCtl'], ['sec2', '加量推荐', 'doseCtl'], ['sec3', '过调抑制', 'oscCtl']].forEach(function (s) {\n      var el = $(s[2]); if (!el) return;\n      secs.push({ id: s[0], title: s[1], html: el.outerHTML, top: el.offsetTop, height: el.offsetHeight });\n    });\n    try { parent.postMessage({ __drawer: 'init', sections: secs }, '*'); } catch (e) {}\n    window.addEventListener('message', function (e) {\n      if (e.source !== window.parent) return;\n      var d = e.data;\n      if (!d || d.__drawer !== 'control') return;\n      var el = doc.querySelector('[data-ctl-id=\"' + d.id + '\"]');\n      if (!el) return;\n      if (el.type === 'range') { el.value = d.value; el.dispatchEvent(new Event('input', { bubbles: true })); }\n      else if (el.tagName === 'BUTTON') { el.click(); }\n    });\n  }\n\n  /* ---------- 启动 ---------- */\n  bind();\n  renderSense(); renderDose(); renderOsc();\n  setupDrawer();\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/flow.js","mime":"text/javascript","data":"/* =========================================================\n   钻井液性能智能调控 · 算法解剖（软测量 + 加量推荐 + 过调抑制）\n   ---------------------------------------------------------\n   把「高频循环参数 → 加量调控」拆成 6 步，每一步都跑真代码：\n\n     ① 多源数据接入  性能测量 + 高频参数 + 加量\n     ② 多源融合软测量  稀疏 → 连续性能趋势\n     ③ 加量推荐      偏差 → 该加多少\n     ④ 过调抑制      按偏差校准，少振荡\n     ⑤ 性能验收      性能 vs 目标窗口\n     ⑥ 加量回流      实际加量 + 性能反馈\n\n   依赖：window.RemoteBridge（demo.js 暴露的真模型）\n        window.AFlow（算法解剖引擎）\n   ========================================================= */\n(function (global) {\n  'use strict';\n\n  var B = global.RemoteBridge;\n  if (!B || !global.AFlow) return;\n\n  var G = global.AFlow.G, C = global.AFlow.C;\n  var M = B.M;\n\n  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }\n  function f(v, n) { return (v == null || !isFinite(v)) ? '—' : Number(v).toFixed(n === undefined ? 2 : n); }\n\n  var N = 100, x0 = 40, w = 300;\n  var C0 = '#41699b', C1 = '#b26a39', C2 = '#2f7d6b';\n\n  function footBox(x, w2, y, h, title, lines, tone) {\n    var bg = tone === 'jade' ? C.jadeL : tone === 'clay' ? C.clayL : tone === 'blue' ? C.blueL : '#f4f3ef';\n    var st = tone === 'jade' ? '#b9d8cb' : tone === 'clay' ? '#e6cdb2' : tone === 'blue' ? '#c5d6ea' : C.line;\n    var fg = tone === 'jade' ? C.jadeD : tone === 'clay' ? '#8a4f27' : tone === 'blue' ? '#2b4a72' : C.ink2;\n    var s = G.rect(x, y, w2, h, { r: 6, fill: bg, stroke: st });\n    if (title) s += G.txt(x + 11, y + 17, title, { size: 9.6, fill: fg, weight: 700 });\n    for (var i = 0; i < lines.length; i++) {\n      s += G.txt(x + 11, y + (title ? 33 : 17) + i * 13, lines[i], { size: 8.8, fill: fg });\n    }\n    return s;\n  }\n\n  function line(arr, x0, y0, xS, yS, color, dash) {\n    var s = '<path d=\"M';\n    for (var i = 0; i < arr.length; i++) {\n      s += (x0 + i * xS).toFixed(1) + ' ' + (y0 - arr[i] * yS).toFixed(1);\n      if (i < arr.length - 1) s += ' L';\n    }\n    s += '\" fill=\"none\" stroke=\"' + color + '\" stroke-width=\"' + (dash ? 1.8 : 2) + '\"' + (dash ? ' stroke-dasharray=\"5 3\"' : '') + '/>';\n    return s;\n  }\n\n  /* ---------- 缓存 ---------- */\n  var cache = { key: '' };\n  function compute() {\n    var L = B.live();\n    var key = [L.nData, L.senseMode, L.recMode].join(',');\n    if (cache.key === key) return cache;\n    var circ = M.genCirc(N, 20261151);\n    var soft = M.softSense(circ, L.senseMode, N, 20261152);\n    var devs = new Float64Array(N);\n    for (var i = 0; i < N; i++) devs[i] = 1.55 - soft.sense[i];\n    var cExp = M.oscillationCtrl(devs, 0, N);\n    var cRec = M.oscillationCtrl(devs, 1, N);\n    cache = { key: key, L: L, circ: circ, soft: soft, devs: devs, cExp: cExp, cRec: cRec };\n    return cache;\n  }\n\n  /* =========================================================\n     ① 多源数据接入\n     ========================================================= */\n  function stage1(t) {\n    var c = compute(), circ = c.circ, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 性能测量', '稀疏·每班1—2次', C.clay);\n    s += G.panel(1, '② 高频循环参数', '流量/温度/压力', C.blue);\n    s += G.panel(2, '③ 加量记录', '动作标签', C.jade);\n\n    var y0 = 130, h = 110;\n    s += G.txt(x0, y0 - 22, '高频循环参数：流量（l/s）+ 温度（℃）', { size: 9.5, fill: C.ink2, weight: 700 });\n    var flowArr = [], tempArr = [];\n    for (var i = 0; i < N; i++) { flowArr.push((circ.flow[i] - 20) / 16); tempArr.push((circ.temp[i] - 42) / 28); }\n    s += line(flowArr, x0, y0 + h, w / N, h, C0, false);\n    s += line(tempArr, x0, y0 + h, w / N, h * 0.8, C2, true);\n    s += G.txt(x0 + 6, y0 - 2, '流量', { size: 7.5, fill: C0 });\n    s += G.txt(x0 + 46, y0 - 2, '温度', { size: 7.5, fill: C2 });\n    s += G.txt(x0, y0 + h + 22, '高频参数与稀疏性能不同步，直接合并会错位', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(420, 170, 130, 180, '多源数据',\n      ['· 性能测量每班1—2次',\n       '· 高频循环参数持续',\n       '· 加量记录是动作标签',\n       '',\n       '高频参数 + 稀疏测量',\n       '要融合，不能直接',\n       '拼。'], 'clay');\n    return { svg: s, stats: [{ k: '性能测量', v: '每班1—2次' }, { k: '高频参数', v: '流量/温度/压力' }], note: '读入钻井液性能测量（稀疏）+ 循环/返出高频参数 + 加量记录。高频参数与稀疏性能时间不同步，直接合并会错位，软测量失真。' };\n  }\n\n  /* =========================================================\n     ② 多源融合软测量\n     ========================================================= */\n  function stage2(t) {\n    var c = compute(), soft = c.soft, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 高频参数', '流量/温度/压力', C.blue);\n    s += G.panel(1, '② 稀疏测量', '每班1—2次', C.clay);\n    s += G.panel(2, '③ 多源融合', '连续性能趋势', C.jade);\n\n    var y0 = 130, h = 110;\n    s += G.txt(x0, y0 - 22, '性能软测量：' + (L.senseMode === 0 ? '纯稀疏' : '多源融合') + ' · 误差 ' + Math.round(soft.err * 100) + '%', { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.axes(x0, y0, w, h, { nx: 4, ny: 3 });\n    var trueArr = [], senseArr = [];\n    for (var i = 0; i < N; i++) { trueArr.push((soft.trueV[i] - 1.0) / 1.2); senseArr.push((soft.sense[i] - 1.0) / 1.2); }\n    s += line(trueArr, x0, y0 + h, w / N, h, C2, true);\n    s += line(senseArr, x0, y0 + h, w / N, h, C0, false);\n    soft.meas.forEach(function (m) {\n      s += G.circle(x0 + m.i * w / N, y0 + h - (m.v - 1.0) / 1.2 * h, 3, { fill: C1 });\n    });\n    s += G.txt(x0 + 6, y0 - 2, '真实', { size: 7.5, fill: C2 });\n    s += G.txt(x0 + 46, y0 - 2, '软测', { size: 7.5, fill: C0 });\n    s += G.txt(x0 + 90, y0 - 2, '实测', { size: 7.5, fill: C1 });\n    s += G.txt(x0, y0 + h + 22, '多源融合用高频参数连续估算 + 稀疏测量校正', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(420, 170, 130, 180, '为什么要融合',\n      ['· 纯稀疏测量跟不上',\n       '  井下变化（滞后）',\n       '· 高频参数连续',\n       '· 融合 = 高频估 +',\n       '  稀疏校正',\n       '',\n       '软测连续趋势。'], 'jade');\n    return { svg: s, stats: [{ k: '软测误差', v: Math.round(soft.err * 100) + '%' }, { k: '实测点', v: soft.meas.length + ' 个' }], note: '用高频循环参数 + 稀疏性能测量，软测出性能的连续变化趋势。只靠性能测量本身、不融合高频参数，软测跟不上井下变化。' };\n  }\n\n  /* =========================================================\n     ③ 加量推荐\n     ========================================================= */\n  function stage3(t) {\n    var c = compute(), devs = c.devs, cRec = c.cRec, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 性能偏差', '实测-目标', C.blue);\n    s += G.panel(1, '② 动作标签', '加量记录', C.jade);\n    s += G.panel(2, '③ 推荐加量', '替代经验', C.clay);\n\n    var y0 = 130, h = 110;\n    s += G.txt(x0, y0 - 22, '推荐加量（按偏差校准）', { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.axes(x0, y0, w, h, { nx: 4, ny: 3 });\n    var doseMax = Math.max.apply(null, Array.from(cRec.recDose)) || 1;\n    var doseArr = [], devArr = [];\n    var devMax = Math.max.apply(null, Array.from(devs).map(function (v) { return Math.abs(v); })) || 1;\n    for (var i = 0; i < N; i++) { doseArr.push(cRec.recDose[i] / (doseMax * 1.1)); devArr.push(devs[i] / (devMax * 1.2)); }\n    s += line(doseArr, x0, y0 + h, w / N, h, C1, false);\n    s += line(devArr, x0, y0 + h, w / N, h, '#7a8a9a', true);\n    s += G.txt(x0 + 6, y0 - 2, '加量', { size: 7.5, fill: C1 });\n    s += G.txt(x0 + 46, y0 - 2, '偏差', { size: 7.5, fill: '#7a8a9a' });\n    s += G.txt(x0, y0 + h + 22, '加量 ∝ 偏差幅度，替代凭经验', { size: 8.5, fill: C.ink3 });\n\n    s += footBox(420, 170, 130, 180, '推荐的坑',\n      ['· 把经验加量当最优',\n       '  标签 → 学到过调',\n       '  行为 → 推荐也过调',\n       '',\n       '要用性能反馈校准',\n       '动作。'], 'clay');\n    return { svg: s, stats: [{ k: '末端加量', v: f(cRec.recDose[N - 1], 2) }, { k: '方法', v: L.recMode === 0 ? '经验' : '推荐' }], note: '用加量记录做动作标签，反推处理剂该加多少。把经验加量当最优标签，学到的是过调行为，推荐也过调。' };\n  }\n\n  /* =========================================================\n     ④ 过调抑制\n     ========================================================= */\n  function stage4(t) {\n    var c = compute(), cExp = c.cExp, cRec = c.cRec, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 经验加量', '过调再回调', C.clay);\n    s += G.panel(1, '② 按偏差校准', '小偏差少加', C.jade);\n    s += G.panel(2, '③ 加量更稳', '少振荡省料', C.blue);\n\n    var y0 = 130, h = 110;\n    s += G.txt(x0, y0 - 22, '加量后性能偏差：经验 vs 推荐', { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.axes(x0, y0, w, h, { nx: 4, ny: 3 });\n    s += G.line(x0, y0 + h / 2, x0 + w, y0 + h / 2, { stroke: '#9ba3a9', sw: 0.8, dash: '4 3' });\n    var expArr = [], recArr = [];\n    for (var i = 0; i < N; i++) { expArr.push(cExp.expPerf[i] / 0.8); recArr.push(cRec.recPerf[i] / 0.8); }\n    s += line(expArr, x0, y0 + h / 2, w / N, h / 2, C1, false);\n    s += line(recArr, x0, y0 + h / 2, w / N, h / 2, C2, false);\n    s += G.txt(x0 + 6, y0 - 2, '经验', { size: 7.5, fill: C1 });\n    s += G.txt(x0 + 46, y0 - 2, '推荐', { size: 7.5, fill: C2 });\n    s += G.txt(x0, y0 + h + 22, '推荐波动 ' + f(cRec.recWave, 2) + ' · 经验 ' + f(cExp.expWave, 2), { size: 8.5, fill: C.ink3 });\n\n    s += footBox(420, 170, 130, 180, '过调的坑',\n      ['· 只按当前偏差猛加',\n       '  → 性能来回摆',\n       '· 处理剂浪费',\n       '',\n       '按偏差幅度校准，',\n       '小偏差少加。'], 'jade');\n    return { svg: s, stats: [{ k: '推荐波动', v: f(cRec.recWave, 2) }, { k: '经验波动', v: f(cExp.expWave, 2) }], note: '推荐加量按偏差幅度校准，偏差小就少加，避免过调再回调振荡。只按当前偏差猛加，不看趋势，性能来回摆，处理剂浪费。' };\n  }\n\n  /* =========================================================\n     ⑤ 性能验收\n     ========================================================= */\n  function stage5(t) {\n    var c = compute(), cRec = c.cRec, L = c.L;\n    var s = '';\n    s += G.panel(0, '① 实际性能', '每班测量', C.blue);\n    s += G.panel(1, '② 目标窗口', '稳定范围', C.clay);\n    s += G.panel(2, '③ 波动幅度', '携岩/井壁', C.jade);\n\n    var y0 = 130, h = 110;\n    s += G.txt(x0, y0 - 22, '性能验收：达标率 推荐 ' + Math.round(cRec.recOk * 100) + '%', { size: 9.5, fill: C.ink2, weight: 700 });\n    s += G.rect(x0, y0, 110, 60, { r: 5, fill: '#d9b78e', op: 1 });\n    s += G.txt(x0 + 55, y0 + 34, Math.round(c.cExp.expOk * 100) + '%', { size: 11, fill: '#4d565b', anchor: 'middle', weight: 700 });\n    s += G.txt(x0 + 55, y0 + 50, '经验加量', { size: 8, fill: '#8a6b52', anchor: 'middle' });\n    s += G.rect(x0 + 170, y0, 110, 60, { r: 5, fill: '#2f7d6b', op: 1 });\n    s += G.txt(x0 + 225, y0 + 34, Math.round(cRec.recOk * 100) + '%', { size: 11, fill: '#fff', anchor: 'middle', weight: 700 });\n    s += G.txt(x0 + 225, y0 + 50, '推荐+抑过调', { size: 8, fill: '#b9d8cb', anchor: 'middle' });\n    s += G.txt(x0, y0 + 76, '达标 ↑ · 波动 ↓ · 携岩好 · 井壁稳', { size: 9, fill: C.jadeD, weight: 700 });\n\n    s += footBox(420, 170, 130, 176, '验收的坑',\n      ['· 只看单次是否达标',\n       '  → 过调问题被掩盖',\n       '· 要看波动幅度',\n       '',\n       '达标率 × 波动。'], 'clay');\n    return { svg: s, stats: [{ k: '推荐达标', v: Math.round(cRec.recOk * 100) + '%' }, { k: '经验达标', v: Math.round(c.cExp.expOk * 100) + '%' }], note: '按班测实际性能，对比目标窗口，看是否稳定。只看单次测量是否达标，不看波动幅度，过调问题被掩盖。' };\n  }\n\n  /* =========================================================\n     ⑥ 加量回流\n     ========================================================= */\n  function stage6(t) {\n    var c = compute(), L = c.L;\n    var s = '';\n    s += G.panel(0, '① 实际加量', '执行结果', C.blue);\n    s += G.panel(1, '② 性能反馈', '是否过调', C.clay);\n    s += G.panel(2, '③ 推荐更准', '振荡下降', C.jade);\n\n    var y0 = 130, h = 110;\n    var rows = [\n      ['加量回流', L.recMode === 0 ? '经验·可能过调' : '推荐·按偏差校准', 'ok'],\n      ['性能反馈', '已录入', 'ok'],\n      ['波动改善', f(c.cExp.expWave - c.cRec.recWave, 2), 'ok'],\n      ['推荐迭代', '已更新', 'ok']\n    ];\n    for (var r = 0; r < rows.length; r++) {\n      var ry = y0 + r * 34;\n      s += G.rect(x0, ry, 360, 26, { r: 4, fill: C.jadeL, stroke: '#b9d8cb' });\n      s += G.txt(x0 + 12, ry + 18, rows[r][0], { size: 8.8, fill: C.ink2, weight: 700 });\n      s += G.txt(x0 + 110, ry + 18, rows[r][1], { size: 8.8, fill: C.jadeD });\n      s += G.txt(x0 + 320, ry + 18, rows[r][2], { size: 8.8, fill: C.jadeD, weight: 700 });\n    }\n    s += G.txt(x0, y0 - 20, '加量回流清单', { size: 9.5, fill: C.ink2, weight: 700 });\n\n    s += footBox(420, 170, 130, 176, '回流的坑',\n      ['· 实际加量不回流',\n       '  → 推荐不知道过调',\n       '  → 振荡不收敛',\n       '',\n       '要闭环校验。'], 'clay');\n    return { svg: s, stats: [{ k: '回流', v: '已录入' }, { k: '波动改善', v: f(c.cExp.expWave - c.cRec.recWave, 2) }], note: '实际加量与性能反馈回流，推荐模型越用越准。实际加量结果不回流，推荐不知道过调了，振荡永远不收敛。' };\n  }\n\n  global.RemoteFlow = { stage1: stage1, stage2: stage2, stage3: stage3, stage4: stage4, stage5: stage5, stage6: stage6 };\n\n})(typeof window !== 'undefined' ? window : global);\n"},{"name":"demo/index.html","mime":"text/html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>示范：钻井液性能智能调控<\/title>\n<link rel=\"stylesheet\" href=\"demo.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aflow.css?v=20261105a\">\n<link rel=\"stylesheet\" href=\"aiq.css?v=20261105a\">\n<style>\n#ctlDrawer{position:fixed;right:0;top:70px;width:268px;max-height:calc(100vh - 120px);overflow-y:auto;background:#fff;border:1px solid #e9e4d8;border-radius:10px;box-shadow:0 6px 24px -8px rgba(0,0,0,.15);z-index:90;transform:translateX(-100%);opacity:0;pointer-events:none;transition:transform .3s ease,opacity .3s ease}\n#ctlDrawer.open{transform:translateX(0);opacity:1;pointer-events:auto}\n@media (max-width:760px){#ctlDrawer{width:calc(100vw - 20px);right:10px;top:auto;bottom:10px;max-height:45vh}}\n.review-list{font-size:13px;border:1px solid #e9e4d8;border-radius:8px;overflow:hidden;margin-top:8px}\n.review-list .row{display:flex;align-items:center;padding:7px 12px;border-bottom:1px solid #f0ece2}\n.review-list .row:last-child{border-bottom:none}\n.review-list .row span{flex:1;color:#4d565b}\n.review-list .row b{width:180px;color:#24333a;font-weight:700}\n.review-list .row em{color:#2f7d6b;font-style:normal;font-weight:700;font-size:12px}\n<\/style>\n<\/head>\n<body>\n\n<header class=\"hd\">\n  <span class=\"kicker\">CASE DEMO · 钻井工程 / 钻井液性能智能调控<\/span>\n  <h1>从「按班测量 · 凭经验加量」到「多源融合软测量 + 加量推荐」<\/h1>\n  <p class=\"sub\">三个实验：Q1 多源融合软测量、Q2 加量推荐、Q3 过调抑制。<\/p>\n<\/header>\n\n<!-- ================= 算法解剖 · 调控全流程 ================= -->\n<section class=\"sec\" id=\"sec0\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">深入 · 想逐帧看就往下<\/span>\n    <p class=\"qa-a\">不是「高频参数 → 黑盒 → 加量」，而是<b>逐段展开<\/b>：数据接入 → 软测量 → 加量推荐 → 过调抑制 → 性能验收 → 加量回流，每一步都能看见中间量<\/p>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">可选深入 · 对应流程 STEP 2—5<\/span>\n    <h2>把「高频循环参数 → 加量调控」一步步拆开看<\/h2>\n    <p class=\"leadline\">下面这段动画跑的是<b>真代码<\/b>（与实验 1—3 同一份模型）。自动播放，也可点阶段名跳步、拖速度。切软测量/加量方式，这里的每一步都会同步重算。<\/p>\n  <\/div>\n  <div id=\"flowMount\"><\/div>\n  <details class=\"more\">\n    <summary>这段动画与后面三个实验是什么关系<\/summary>\n    <div class=\"more-body\">\n      <p>实验 1—3 给出的是<b>结果<\/b>（软测趋势、推荐加量、波动对比）；这段动画给出的是<b>过程<\/b>——同一份 <code>demo.js<\/code> 里的 <code>softSense / doseRecommend / oscillationCtrl<\/code> 被拆成 6 个阶段依次放慢演给你看。<\/p>\n      <p>刻意做的两处细节：<b>①<\/b> 第 2 步把真实与软测性能同框，看得见「多源融合」贴近真实；<b>②<\/b> 第 4 步把经验与推荐加量后的性能偏差同框，看得见「过调抑制」让曲线更稳。<\/p>\n    <\/div>\n  <\/details>\n<\/section>\n\n<!-- ================= 实验 1 · 多源融合软测量 ================= -->\n<section class=\"sec\" id=\"sec1\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q1 · 为什么需要智能算法<\/span>\n    <p class=\"qa-a\">性能测量每班 1—2 次，变化滞后井下；高频参数没用起来<\/p>\n    <button class=\"qa-go\">开始实验 1<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 1 · 对应流程 STEP 1—2<\/span>\n    <h2>多源融合软测量：稀疏性能 → 连续趋势<\/h2>\n    <p class=\"leadline\">切「纯稀疏测量 / 多源融合」，看软测性能与真实差距。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"senseCtl\">\n    <div class=\"sl\">\n      <label>测量方式<output id=\"outSense\">多源融合<\/output><\/label>\n      <input type=\"range\" id=\"inSense\" min=\"0\" max=\"1\" step=\"1\" value=\"1\">\n    <\/div>\n  <\/div>\n  <svg id=\"senseChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"多源融合软测量\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">软测误差<\/span><b id=\"roErr\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">数据来源<\/span><b id=\"roSrc\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"senseTip\">性能每班才测 1—2 次，纯稀疏测量跟不上下井变化（阶梯状、滞后）。多源融合用高频循环参数（流量/温度/压力）连续估算 + 稀疏测量点校正，软测出连续性能趋势，误差大幅下降。<\/p>\n<\/section>\n\n<!-- ================= 实验 2 · 加量推荐 ================= -->\n<section class=\"sec\" id=\"sec2\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q2 · 智能算法是什么<\/span>\n    <p class=\"qa-a\"><b>加量推荐<\/b>：偏差 → 该加多少（用加量记录做动作标签）<span class=\"qa-algo\">多源融合软测量 · 加量推荐<\/span><\/p>\n    <button class=\"qa-go\">开始实验 2<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 2 · 对应流程 STEP 3<\/span>\n    <h2>加量推荐：偏差 → 处理剂该加多少<\/h2>\n    <p class=\"leadline\">切「经验加量 / 推荐」，看加量随偏差怎么变。<\/p>\n  <\/div>\n  <div class=\"ctl\" id=\"doseCtl\">\n    <div class=\"sl\">\n      <label>加量方式<output id=\"outRec\">推荐+抑过调<\/output><\/label>\n      <input type=\"range\" id=\"inRec\" min=\"0\" max=\"1\" step=\"1\" value=\"1\">\n    <\/div>\n  <\/div>\n  <svg id=\"doseChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"加量推荐\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">末端加量<\/span><b id=\"roDose\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">性能偏差<\/span><b id=\"roDev\">—<\/b><\/div>\n  <\/div>\n  <p class=\"tip\" id=\"doseTip\">经验加量按偏差猛加、容易过调；推荐加量按偏差幅度校准（小偏差少加）。加量记录做动作标签、反推该加多少，替代凭经验。但若把经验加量当最优标签，学到的是过调行为，推荐也过调。<\/p>\n<\/section>\n\n<!-- ================= 实验 3 · 过调抑制 ================= -->\n<section class=\"sec\" id=\"sec3\">\n  <div class=\"qa\">\n    <span class=\"qa-q\">Q3 · 它怎么工作<\/span>\n    <p class=\"qa-a\">加量后性能偏差更小 → <b>过调抑制<\/b>（少振荡、省料）<\/p>\n    <button class=\"qa-go\">开始实验 3<\/button>\n  <\/div>\n  <div class=\"sec-hd\">\n    <span class=\"sec-no\">实验 3 · 对应流程 STEP 4—6<\/span>\n    <h2>过调抑制：经验 vs 推荐加量 + 性能验收<\/h2>\n    <p class=\"leadline\">看经验与推荐加量后的性能偏差，达标率差多少、回流清单。<\/p>\n  <\/div>\n  <svg id=\"oscChart\" viewBox=\"0 0 400 200\" role=\"img\" aria-label=\"过调抑制\"><\/svg>\n  <div class=\"rrow ro2\">\n    <div class=\"ro\"><span class=\"k\">波动幅度<\/span><b id=\"roWave\">—<\/b><\/div>\n    <div class=\"ro\"><span class=\"k\">达标率<\/span><b id=\"roOk\">—<\/b><\/div>\n  <\/div>\n  <div class=\"review-list\" id=\"reviewList\"><\/div>\n  <p class=\"tip\" id=\"oscTip\">经验加量过调再回调、性能来回摆、处理剂浪费；推荐加量按偏差校准、性能更稳、达标率更高。实际加量与性能反馈回流模型，推荐越用越准、振荡持续下降。<\/p>\n<\/section>\n\n<footer>\n  <div class=\"map\">\n    <div><b>实验 1 → STEP 2<\/b><br>多源融合软测量。<\/div>\n    <div><b>实验 2 → STEP 3<\/b><br>加量推荐替代经验。<\/div>\n    <div><b>实验 3 → STEP 4<\/b><br>过调抑制 + 回流。<\/div>\n  <\/div>\n  <p class=\"note\">纯前端教学演示：循环参数与性能由「基波 + 趋势 + 噪声」合成，目标窗口已知、仅供对比；多源融合软测量、加量推荐与过调抑制均在浏览器实时计算。<\/p>\n<\/footer>\n\n<script src=\"demo.js\"><\/script>\n<script src=\"aflow.js\"><\/script>\n<script src=\"flow.js\"><\/script>\n<script>\n/* 算法解剖：把 6 个阶段挂到 AFlow 引擎上 */\n(function () {\n  if (!window.AFlow || !window.RemoteFlow) return;\n  var F = window.RemoteFlow;\n  window.RemoteFlowApi = window.AFlow.create({\n    mount: document.getElementById('flowMount'),\n    title: '算法解剖',\n    subtitle: '自动播放：高频循环参数怎么一步步变成加量调控',\n    stages: [\n      { name: '数据接入', tag: '多源数据', dur: 4000, draw: function (t, g) { return F.stage1(t); } },\n      { name: '多源融合软测量', tag: '连续趋势', dur: 4600, draw: function (t, g) { return F.stage2(t); } },\n      { name: '加量推荐', tag: '该加多少', dur: 4400, draw: function (t, g) { return F.stage3(t); } },\n      { name: '过调抑制', tag: '少振荡', dur: 4600, draw: function (t, g) { return F.stage4(t); } },\n      { name: '性能验收', tag: '达标率', dur: 4200, draw: function (t, g) { return F.stage5(t); } },\n      { name: '加量回流', tag: '更准', dur: 4200, draw: function (t, g) { return F.stage6(t); } }\n    ]\n  });\n})();\n<\/script>\n<script src=\"aiq.js?v=20261105a\"><\/script>\n<\/body>\n<\/html>\n"}];
  var CFG = {"mode":"auto","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"用合成的循环参数与稀疏性能测量演示多源融合软测量、加量推荐与过调抑制。","height":600};
  var META = {"id":"d5-mud-control","sceneId":"d5","title":"钻井液性能智能调控：多源融合 + 加量推荐抑制过调"};
  var handle = null;
  var DEF = {"id":"d5-mud-control","sceneId":"d5","title":"钻井液性能智能调控：多源融合 + 加量推荐抑制过调","methods":["ts","opt"],"version":"1.0.0","updated":"2026-11-05","status":"ready","tabs":{"background":{"label":"专业背景","judge":[{"label":"数据形态","value":"稀疏测量+高频循环","desc":"性能每班1—2次"},{"label":"标注成本","value":"低","desc":"加量记录是动作标签"},{"label":"可见收益","value":"性能稳定+少过调","desc":"井壁稳定携岩好"},{"label":"难度","value":"中","desc":"多源融合+软测量"}],"lede":"钻井液的密度、黏度、滤失量直接影响井壁稳定与携岩能力，现场按班测量并人工调整处理剂加量。测量间隔长（每班 1—2 次），性能变化滞后于井下实际；处理剂加量靠经验，常出现「过调」再「回调」的振荡。智能方法用返出参数与循环温度等高频信号软测量性能变化趋势，反推处理剂加量建议。","sections":[{"no":1,"en":"PROBLEM","title":"当前做法与问题","html":"<p>钻井液的<b>密度、黏度、滤失量<\/b>直接影响井壁稳定与携岩能力。现场<b>按班测量<\/b>并人工调整<b>处理剂加量<\/b>。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>测量稀疏<\/b>——每班 1—2 次，性能变化滞后于井下实际<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>加量靠经验<\/b>——处理剂加量凭感觉，常「过调」再「回调」振荡<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>影响大<\/b>——性能失衡影响井壁稳定与携岩，严重时卡钻<\/span><\/div><\/div><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"人工调浆的问题\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">按班测量 + 凭经验加量 → 滞后 · 过调振荡<\/text><rect x=\"20\" y=\"36\" width=\"280\" height=\"176\" rx=\"8\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"160\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">人工调浆<\/text><rect x=\"36\" y=\"70\" width=\"120\" height=\"30\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"96\" y=\"90\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#2b4a72\">每班测 1—2 次<\/text><rect x=\"180\" y=\"70\" width=\"100\" height=\"30\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"230\" y=\"90\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">凭经验加量<\/text><rect x=\"36\" y=\"112\" width=\"120\" height=\"30\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"96\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">变化滞后井下<\/text><rect x=\"180\" y=\"112\" width=\"100\" height=\"30\" rx=\"5\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"230\" y=\"132\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8a4f27\">过调再回调<\/text><text x=\"160\" y=\"180\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#b26a39\" font-weight=\"700\">性能失衡影响井壁/携岩<\/text><text x=\"160\" y=\"198\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#79828a\">严重时卡钻<\/text><rect x=\"316\" y=\"36\" width=\"284\" height=\"176\" rx=\"8\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"458\" y=\"56\" text-anchor=\"middle\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">为什么难<\/text><text x=\"332\" y=\"82\" font-size=\"9.5\" fill=\"#4d565b\">· 性能测量频率低、标签稀疏<\/text><text x=\"332\" y=\"104\" font-size=\"9.5\" fill=\"#4d565b\">· 需与高频循环参数融合<\/text><text x=\"332\" y=\"126\" font-size=\"9.5\" fill=\"#4d565b\">· 加量凭经验易过调<\/text><rect x=\"332\" y=\"150\" width=\"252\" height=\"46\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"344\" y=\"170\" font-size=\"8.5\" fill=\"#79828a\">返出参数/循环温度<\/text><text x=\"344\" y=\"186\" font-size=\"8.5\" fill=\"#b26a39\" font-weight=\"700\">高频信号没用起来<\/text><\/svg><\/div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>用<b>多源融合 + 软测量<\/b>：把高频的循环/返出参数（流量、温度、压力）与稀疏的钻井液性能测量融合，软测出性能的<b>连续变化趋势<\/b>；再用加量记录做<b>动作标签<\/b>，反推处理剂加量建议，<b>抑制过调<\/b>。<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>多源融合软测量<\/b>——高频循环参数 + 稀疏性能测量，软测连续性能趋势<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>加量推荐<\/b>——加量记录做动作标签，反推处理剂该加多少<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>抑制过调<\/b>——推荐按偏差幅度校准，避免「过调再回调」振荡<\/span><\/div><\/div><p>落地形态：性能稳定、携岩好、井壁稳，处理剂加量少振荡、省料。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"钻井液智能调控流程\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">多源融合软测量 + 加量推荐 + 抑制过调<\/text><rect x=\"20\" y=\"40\" width=\"120\" height=\"120\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"80\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#242b2e\" font-weight=\"600\">高频循环参数<\/text><path d=\"M36 78 C60 62 90 76 116 68\" fill=\"none\" stroke=\"#7a8a9a\" stroke-width=\"2.6\"/><text x=\"80\" y=\"130\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">流量/温度/压力<\/text><path d=\"M144 100 L168 100\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"172\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"237\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">多源融合软测量<\/text><text x=\"237\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">稀疏测量+高频<\/text><text x=\"237\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">连续性能趋势<\/text><path d=\"M306 100 L330 100\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"334\" y=\"40\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"399\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#2b4a72\" font-weight=\"600\">加量推荐<\/text><text x=\"399\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">动作标签<\/text><text x=\"399\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">反推加多少<\/text><path d=\"M468 100 L492 100\" stroke=\"#2b4a72\" stroke-width=\"1.6\"/><rect x=\"496\" y=\"40\" width=\"104\" height=\"120\" rx=\"6\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"548\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">抑制过调<\/text><text x=\"548\" y=\"82\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">按偏差校准<\/text><text x=\"548\" y=\"98\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#4d565b\">少振荡省料<\/text><text x=\"310\" y=\"210\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#22604f\" font-weight=\"600\">性能稳定 · 携岩好 · 井壁稳 · 加量少振荡<\/text><\/svg><\/div>"},{"no":3,"en":"DATA","title":"需要准备什么","html":"<p><b>钻井液性能测量<\/b>：密度、黏度、滤失、含砂，每班 1—2 次，样本稀疏；<b>循环与返出参数<\/b>：流量、温度、压力，高频；<b>处理剂加量记录<\/b>：类型、加量、时间，作为动作标签。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"钻井液调控数据准备\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">钻井液智能调控需要的数据<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#41699b\"/><text x=\"32\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">钻井液性能测量<\/text><text x=\"32\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">密度/黏度/滤失/含砂<\/text><text x=\"32\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">每班 1—2 次，样本稀疏<\/text><rect x=\"318\" y=\"34\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"34\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#b26a39\"/><text x=\"330\" y=\"54\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">循环与返出参数<\/text><text x=\"330\" y=\"72\" font-size=\"8.8\" fill=\"#79828a\">流量/温度/压力<\/text><text x=\"330\" y=\"88\" font-size=\"8.5\" fill=\"#9ba3a9\">高频<\/text><rect x=\"20\" y=\"106\" width=\"286\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"20\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#2f7d6b\"/><text x=\"32\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">处理剂加量记录<\/text><text x=\"32\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">类型/加量/时间<\/text><text x=\"32\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">动作标签<\/text><rect x=\"318\" y=\"106\" width=\"284\" height=\"64\" rx=\"6\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><rect x=\"318\" y=\"106\" width=\"4\" height=\"64\" rx=\"2\" fill=\"#79828a\"/><text x=\"330\" y=\"126\" font-size=\"10\" fill=\"#242b2e\" font-weight=\"600\">井下工况<\/text><text x=\"330\" y=\"144\" font-size=\"8.8\" fill=\"#79828a\">钻速/井深/岩性<\/text><text x=\"330\" y=\"160\" font-size=\"8.5\" fill=\"#9ba3a9\">影响性能需求<\/text><rect x=\"20\" y=\"184\" width=\"582\" height=\"26\" rx=\"6\" fill=\"#f8ecdf\"/><text x=\"32\" y=\"202\" font-size=\"9.5\" fill=\"#8a4f27\" font-weight=\"600\">训练策略：多源融合 + 软测量 + 加量推荐 + 过调抑制<\/text><\/svg><\/div>"},{"no":4,"en":"DIFFICULTY","title":"难度与参考方向","html":"<p>三个最容易翻车的点：<\/p><div class=\"enlist\"><div class=\"it\"><span class=\"no\">①<\/span><span class=\"tx\"><b>标签稀疏<\/b>——性能每班才测 1—2 次，监督信号稀疏，纯靠性能测量学不好<\/span><\/div><div class=\"it\"><span class=\"no\">②<\/span><span class=\"tx\"><b>需多源融合<\/b>——性能变化滞后井下，高频循环参数是重要的软测量输入<\/span><\/div><div class=\"it\"><span class=\"no\">③<\/span><span class=\"tx\"><b>加量易过调<\/b>——凭经验加量常「过调再回调」，振荡浪费处理剂<\/span><\/div><\/div><p>改进路线按成本从低到高：先用<b>软测量<\/b>把稀疏性能与高频参数融合、软测连续趋势；再加<b>加量推荐<\/b>用动作标签反推该加多少；最后加<b>过调抑制<\/b>按偏差幅度校准，减少振荡。<\/p><div class=\"figure\"><svg viewBox=\"0 0 620 210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"钻井液调控难点与对策\" style=\"width:100%;height:auto;display:block\"><text x=\"310\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#242b2e\" font-weight=\"600\">难点排序 + 成本从低到高的改进路线<\/text><rect x=\"20\" y=\"34\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"52\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">① 标签稀疏<\/text><text x=\"32\" y=\"68\" font-size=\"8.5\" fill=\"#6b4a35\">性能每班1—2次<\/text><path d=\"M310 57 L356 57\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"34\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"52\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">多源融合软测量<\/text><text x=\"372\" y=\"68\" font-size=\"8.5\" fill=\"#4d565b\">高频补稀疏<\/text><rect x=\"20\" y=\"86\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"104\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">② 需多源融合<\/text><text x=\"32\" y=\"120\" font-size=\"8.5\" fill=\"#6b4a35\">性能滞后井下<\/text><path d=\"M310 109 L356 109\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"86\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"104\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">循环/返出参数<\/text><text x=\"372\" y=\"120\" font-size=\"8.5\" fill=\"#4d565b\">流量/温度/压力<\/text><rect x=\"20\" y=\"138\" width=\"286\" height=\"46\" rx=\"6\" fill=\"#f9efea\" stroke=\"#d8a48c\"/><text x=\"32\" y=\"156\" font-size=\"10\" fill=\"#8a4f27\" font-weight=\"600\">③ 加量易过调<\/text><text x=\"32\" y=\"172\" font-size=\"8.5\" fill=\"#6b4a35\">过调再回调振荡<\/text><path d=\"M310 161 L356 161\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"360\" y=\"138\" width=\"242\" height=\"46\" rx=\"6\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"372\" y=\"156\" font-size=\"10\" fill=\"#22604f\" font-weight=\"600\">加量推荐+过调抑制<\/text><text x=\"372\" y=\"172\" font-size=\"8.5\" fill=\"#4d565b\">按偏差校准<\/text><rect x=\"20\" y=\"192\" width=\"582\" height=\"16\" rx=\"8\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#41699b\">软测量 → 加量推荐 → 过调抑制<\/text><\/svg><\/div>"}]},"workflow":{"label":"案例流程","title":"案例：一口井的钻井液性能调控改造","lead":["某井此前按班测钻井液性能、凭经验加处理剂，性能变化滞后井下、加量过调振荡。目标：用多源融合软测量连续追踪性能趋势，用加量推荐替代经验，抑制过调。","注意第 3、4、5 步：多源融合软测量、加量推荐、过调抑制是智能化价值的三个落点，示范页三屏一一对应。"],"stats":[["井","某生产井"],["性能测量","每班 1—2 次"],["加量方式","凭经验"],["高频参数","流量/温度/压力"],["目标","软测量+推荐+抑过调"],["难点","标签稀疏"]],"steps":[{"name":"多源数据接入","role":"数据","do":"读入钻井液性能测量（稀疏）+ 循环/返出高频参数 + 加量记录。示范页屏 1 顶部可看高频参数。","effect":"稀疏性能 + 高频循环参数 + 加量动作标签，多源数据集。","trap":"高频参数与稀疏性能时间不同步，直接合并会错位，软测量失真。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">数据接入：性能测量 + 高频参数 + 加量<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">性能测量<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">每班 1—2 次<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">高频循环参数<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">流量/温度/压力<\/text><path d=\"M360 72 L384 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">加量记录<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">动作标签<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：高频与稀疏时间不同步 → 直接合并错位 → 软测量失真<\/text><\/svg>"},{"name":"多源融合软测量","role":"算法核心","do":"用高频循环参数 + 稀疏性能测量，软测出性能的连续变化趋势。示范页屏 1 展示软测 vs 实测。","effect":"一个连续追踪的性能趋势，替代每班一次的稀疏测量。","trap":"只靠性能测量本身、不融合高频参数，软测跟不上井下变化。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">软测量：高频参数 → 连续性能趋势<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">高频循环参数<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">流量/温度/压力<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">多源融合<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">软测量模型<\/text><path d=\"M360 72 L384 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">连续性能趋势<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">密度/黏度<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只靠性能测量不融合高频 → 软测跟不上井下变化<\/text><\/svg>"},{"name":"加量推荐","role":"算法核心","do":"用加量记录做动作标签，反推处理剂该加多少。示范页屏 2 展示推荐加量。","effect":"一个基于偏差的处理剂加量建议，替代凭经验。","trap":"把「经验加量」当最优标签，学到的是过调行为，推荐也过调。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">加量推荐：偏差 → 该加多少<\/text><rect x=\"24\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"99\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">性能偏差<\/text><text x=\"99\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">实测-目标<\/text><path d=\"M178 72 L202 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"206\" y=\"42\" width=\"150\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"281\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">动作标签<\/text><text x=\"281\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">加量记录<\/text><path d=\"M360 72 L384 72\" stroke=\"#2f7d6b\" stroke-width=\"1.6\"/><rect x=\"388\" y=\"42\" width=\"206\" height=\"60\" rx=\"5\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"491\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#242b2e\" font-weight=\"600\">推荐加量<\/text><text x=\"491\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">替代经验<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：把经验加量当最优标签 → 学到过调行为 → 推荐也过调<\/text><\/svg>"},{"name":"过调抑制","role":"算法核心","do":"推荐加量按偏差幅度校准，偏差小就少加，避免过调再回调振荡。示范页屏 3 展示经验 vs 推荐加量曲线。","effect":"加量更稳，性能波动小，处理剂省料。","trap":"只按当前偏差猛加，不看趋势，性能来回摆，处理剂浪费。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">过调抑制：按偏差幅度校准加量<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">经验加量<\/text><text x=\"104\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">过调再回调<\/text><path d=\"M188 72 L210 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">按偏差校准<\/text><text x=\"294\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">小偏差少加<\/text><path d=\"M378 72 L400 72\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">加量更稳<\/text><text x=\"499\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">少振荡省料<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只按当前偏差猛加不看趋势 → 性能来回摆 → 处理剂浪费<\/text><\/svg>"},{"name":"性能验收","role":"人工确认","do":"按班测实际性能，对比目标窗口，看是否稳定。示范页屏 3 展示性能验收。","effect":"性能稳定在目标窗口内，携岩好、井壁稳。","trap":"只看单次测量是否达标，不看波动幅度，过调问题被掩盖。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">验收：性能 vs 目标窗口 → 波动幅度<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">实际性能<\/text><text x=\"104\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">每班测量<\/text><path d=\"M188 72 L210 72\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"60\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">目标窗口<\/text><text x=\"294\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">稳定范围<\/text><path d=\"M378 72 L400 72\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"60\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"62\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">波动幅度<\/text><text x=\"499\" y=\"80\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">携岩/井壁<\/text><text x=\"24\" y=\"128\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：只看单次达标不看波动 → 过调问题被掩盖<\/text><\/svg>"},{"name":"加量回流","role":"人工确认","do":"实际加量与性能反馈回流，推荐模型越用越准。示范页屏 3 展示回流清单。","effect":"加量推荐更准，过调振荡持续下降。","trap":"实际加量结果不回流，推荐不知道过调了，振荡永远不收敛。","fig":"<svg viewBox=\"0 0 620 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"1\" y=\"1\" width=\"618\" height=\"148\" rx=\"10\" fill=\"#fbfaf6\" stroke=\"#e9e4d8\"/><text x=\"24\" y=\"30\" font-size=\"12\" fill=\"#4d565b\" font-weight=\"600\">回流：实际加量 + 性能 → 推荐更准<\/text><rect x=\"24\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#e7eef9\" stroke=\"#41699b\"/><text x=\"104\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#2b4a72\" font-weight=\"600\">实际加量<\/text><text x=\"104\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">执行结果<\/text><path d=\"M188 68 L210 68\" stroke=\"#9ba3a9\" stroke-width=\"1.6\"/><rect x=\"214\" y=\"42\" width=\"160\" height=\"52\" rx=\"5\" fill=\"#f7ece2\" stroke=\"#b26a39\"/><text x=\"294\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#8a4f27\" font-weight=\"600\">性能反馈<\/text><text x=\"294\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">是否过调<\/text><path d=\"M378 68 L400 68\" stroke=\"#b26a39\" stroke-width=\"1.6\"/><rect x=\"404\" y=\"42\" width=\"190\" height=\"52\" rx=\"5\" fill=\"#e6f1ec\" stroke=\"#2f7d6b\"/><text x=\"499\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#22604f\" font-weight=\"600\">推荐更准<\/text><text x=\"499\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#79828a\">振荡持续降<\/text><text x=\"24\" y=\"120\" font-size=\"8.5\" fill=\"#8a4f27\">陷阱：实际加量不回流 → 推荐不知道过调 → 振荡不收敛<\/text><\/svg>"}],"metrics":{"title":"怎么算「调控对了」","html":"<p>钻井液调控用 <b>性能达标率<\/b>（性能落在目标窗口）与 <b>波动幅度<\/b>（标准差）双重验收；<b>处理剂用量<\/b>衡量省料成本。<\/p><p>最终还要看 <b>过调抑制<\/b>：加量是否稳定、性能是否来回振荡。<\/p><p style=\"margin-top:16px\"><svg viewBox='0 0 620 200' xmlns='http://www.w3.org/2000/svg' role='img' aria-label='钻井液调控效果对比' style='width:100%;height:auto;display:block'><text x='14' y='20' font-size='10' fill='#4d565b' font-weight='600'>钻井液调控验收：达标率 × 波动 × 省料<\/text><rect x='14' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='159' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>调控效果<\/text><rect x='40' y='66' width='80' height='52' fill='#d9b78e'/><text x='80' y='96' text-anchor='middle' font-size='10' fill='#4d565b' font-weight='700'>达标 68%<\/text><text x='80' y='112' text-anchor='middle' font-size='8' fill='#8a6b52'>经验加量<\/text><rect x='180' y='66' width='80' height='52' fill='#2f7d6b'/><text x='220' y='96' text-anchor='middle' font-size='10' fill='#fff' font-weight='700'>达标 94%<\/text><text x='220' y='112' text-anchor='middle' font-size='8' fill='#b9d8cb'>推荐+抑过调<\/text><text x='159' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>达标 ↑ 波动 ↓<\/text><rect x='316' y='34' width='290' height='120' rx='8' fill='#fbfaf6' stroke='#e9e4d8'/><text x='461' y='54' text-anchor='middle' font-size='9.5' fill='#242b2e' font-weight='600'>波动 + 省料<\/text><rect x='340' y='66' width='120' height='52' fill='#e7eef9' stroke='#41699b'/><text x='400' y='92' text-anchor='middle' font-size='9' fill='#2b4a72' font-weight='700'>波动幅度↓<\/text><text x='400' y='108' text-anchor='middle' font-size='8' fill='#79828a'>性能稳定<\/text><rect x='470' y='66' width='120' height='52' fill='#e6f1ec' stroke='#2f7d6b'/><text x='530' y='92' text-anchor='middle' font-size='9' fill='#22604f' font-weight='700'>处理剂省料<\/text><text x='530' y='108' text-anchor='middle' font-size='8' fill='#79828a'>少过调<\/text><text x='461' y='146' text-anchor='middle' font-size='8.5' fill='#79828a'>携岩好 · 井壁稳<\/text><text x='310' y='188' text-anchor='middle' font-size='8' fill='#9ba3a9'>验收 = 达标率 × 波动幅度 × 省料<\/text><\/svg><\/p>"},"fails":[{"name":"标签稀疏","why":"性能每班才测 1—2 次，监督信号稀疏，纯靠性能测量学不好软测量。"},{"name":"需多源融合","why":"性能变化滞后井下，高频循环参数是重要软测量输入，不融合就跟不上。"},{"name":"加量易过调","why":"凭经验加量常过调再回调，振荡浪费处理剂、性能不稳。"},{"name":"经验加量非最优标签","why":"把经验加量当最优标签，学到的是过调行为，推荐也过调。"}]}}};
  DEF.tabs.demo = {
    label: "可运行示范",
    intro: "用合成的循环参数与稀疏性能测量演示多源融合软测量、加量推荐与过调抑制。",
    mode: "page",
    mount: function (root, ctx) {
      handle = window.CaseDemoHost.create(root, { files: FILES, demo: CFG, meta: META }, ctx);
    },
    unmount: function () {
      if (handle) { try { handle.destroy(); } catch (e) { } handle = null; }
    }
  };
  window.Cases.register(DEF);
})();
